"""Pygame GUI for PylonChess with menu, AI opponents, resize and fullscreen."""

import json
import os
import random
import subprocess
import time
import threading
import pygame

from pylonchess.board import ChessBoard
from pylonchess.pieces import Color, PieceType
from pylonchess.ai import ChessAI
from pylonchess.sound import SoundManager


# Colors
LIGHT_SQUARE = (240, 217, 181)
DARK_SQUARE = (181, 136, 99)
HIGHLIGHT_COLOR = (186, 202, 68)
CHECK_COLOR = (235, 97, 80)
LAST_MOVE_COLOR = (205, 210, 106)
HINT_COLOR = (90, 170, 255)
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)
GRAY = (150, 150, 150)
DARK_GRAY = (48, 48, 48)
PANEL = (36, 36, 36)
BUTTON = (70, 100, 160)
BUTTON_HOVER = (100, 140, 210)
BUTTON_ACTIVE = (60, 160, 90)
BUTTON_ACTIVE_HOVER = (80, 190, 110)
FOCUS_COLOR = (255, 220, 80)

BOARD_COORD_BORDER = 22  # width of coordinate label border around the board

DIFFICULTIES = ["easy", "medium", "hard"]
DIFFICULTY_LABELS = {"easy": "Eenvoudig", "medium": "Gemiddeld", "hard": "Sterk"}
SIZES = [("Klein", 60), ("Normaal", 80), ("Groot", 100)]
SCALED_MAX_H = 625   # max logical window height once desktop scaling is applied
SCALED_MAX_W = 1170  # max logical window width once desktop scaling is applied

# Point values per piece (capture mode / display). The engine's own search
# scores in board.PIECE_VALUES are left untouched.
CAPTURE_POINTS = {
    PieceType.PAWN: 1,
    PieceType.KNIGHT: 3,
    PieceType.BISHOP: 3,
    PieceType.ROOK: 5,
    PieceType.QUEEN: 9,
    PieceType.KING: 20,  # never actually captured in normal play
}


class Button:
    PRESS_DURATION = 0.14   # seconds the pressed animation plays

    def __init__(self, rect, text, font, base_color=None, hover_color=None):
        self.rect = pygame.Rect(rect)
        self.text = text
        self.font = font
        self.active = False
        self.hover = False
        self.focused = False
        self.base_color = base_color if base_color is not None else BUTTON
        self.hover_color = hover_color if hover_color is not None else BUTTON_HOVER
        self.pressed_until = 0.0

    def press(self):
        """Trigger the short 'pressed' squeeze animation."""
        self.pressed_until = time.time() + Button.PRESS_DURATION

    def is_pressed(self):
        return time.time() < self.pressed_until

    def handle_event(self, event):
        if event.type == pygame.MOUSEMOTION:
            self.hover = self.rect.collidepoint(event.pos)
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            return self.rect.collidepoint(event.pos)
        return False

    def draw(self, screen):
        if self.active:
            base = BUTTON_ACTIVE_HOVER if self.hover else BUTTON_ACTIVE
            border = (80, 190, 110)
        else:
            base = self.hover_color if self.hover else self.base_color
            border = WHITE
        if self.focused:
            border = FOCUS_COLOR
        if self.is_pressed():
            rect = self.rect.move(0, 2)
            rect = rect.inflate(-4, -4)
            base = tuple(max(0, c - 35) for c in base)
        else:
            rect = self.rect
        pygame.draw.rect(screen, base, rect, border_radius=8)
        width = 4 if self.focused else 2
        pygame.draw.rect(screen, border, rect, width, border_radius=8)
        text = self.font.render(self.text, True, WHITE)
        screen.blit(text, text.get_rect(center=rect.center))


class ChessGUI:
    def __init__(self):
        pygame.init()
        self.sound = SoundManager()
        self.square_size = 80
        self.fullscreen = False
        self.sidebar_width = 280

        # Start with the largest board size that fits the (scaled) screen.
        # Choosing a bigger size in the menu afterwards is always honored.
        self.square_size = self._fit_size(80)

        # Layout: top capture strip + 8-square board + bottom capture strip + status
        self._compute_layout(self.square_size)

        self.font_large = pygame.font.Font(None, 40)
        self.font_medium = pygame.font.Font(None, 24)
        self.font_small = pygame.font.Font(None, 20)
        self.font_tiny = pygame.font.Font(None, 18)
        self.clock = pygame.time.Clock()

        # Menu defaults
        self.ai_difficulty = "medium"
        self.ai_side = Color.BLACK
        self.pvp_bottom = Color.WHITE  # which color's pieces are at the bottom in PvP mode
        self.mode = "ai"  # default game mode selected in the menu
        self.timer_type = "off"   # "off" / "clock" / "capture"
        self.timer_minutes = 10   # minutes per player (clock)
        self.focus_index = 0      # keyboard focus index in menu_buttons

        # Hint, promotion and feedback state (also reset in _reset_game)
        self.hint_move = None
        self.hint_thinking = False
        self._hint_ai = ChessAI(self.ai_difficulty)
        self._pending_promotion = None
        self._promo_buttons = []
        self._promo_panel = None
        self._played_game_over_sound = False
        self._notice = None
        self._menu_notice = None
        self._menu_frame = None

        self._reset_game()
        self.ai = ChessAI("medium")

        # Display
        self.screen = pygame.display.set_mode((self.screen_width, self.screen_height))
        self._screen_width = self.screen_width
        self._screen_height = self.screen_height
        pygame.display.set_caption("PylonChess")
        self._center_window()

        # Slot overlay (save/load chooser) state
        self._slot_mode = None       # "save", "load" or "delete", None when closed
        self._slot_return = None     # state to return to after the overlay
        self._slot_title = None
        self._slot_panel = None
        self._slot_buttons = []      # list of (rect, SlotButton)
        self._slot_tabs = []         # list of (rect, mode)
        self._slot_cancel_rect = None
        self._slot_confirm = None    # slot n pending delete confirmation
        self._slot_confirm_yes = None
        self._slot_confirm_no = None
        self._slot_focus = 0
        self._slot_pad = 26

        self._migrate_legacy_save()

        self.state = "menu"
        self.menu_buttons = []
        self._build_menu()

    # ---------------------------------------------------------------- layout
    def _compositor_scale(self):
        """The monitor's scaling factor (1.0, 1.25, 1.5, 1.6, ...) as reported
        by the compositor. Falls back to 1.0 when it cannot be queried."""
        try:
            out = subprocess.check_output(
                ["hyprctl", "monitors", "-j"], stderr=subprocess.DEVNULL, timeout=3
            )
            mons = json.loads(out.decode("utf-8", "replace"))
            if not isinstance(mons, list) or not mons:
                return 1.0
            primary = None
            for m in mons:
                if isinstance(m, dict) and m.get("x", 0) == 0 and m.get("y", 0) == 0:
                    primary = m
                    break
            m = primary or (mons[0] if isinstance(mons[0], dict) else None)
            if not m:
                return 1.0
            sc = float(m.get("scale") or 1.0)
            return sc if sc > 0 else 1.0
        except Exception:
            return 1.0

    def _top_reserved(self):
        """Vertical space (logical px) reserved at the top of the screen by the
        compositor for bars such as the Omarchy shell. 0 when unknown."""
        try:
            out = subprocess.check_output(
                ["hyprctl", "monitors", "-j"], stderr=subprocess.DEVNULL, timeout=3
            )
            mons = json.loads(out.decode("utf-8", "replace"))
            if not isinstance(mons, list) or not mons:
                return 0
            primary = None
            for m in mons:
                if isinstance(m, dict) and m.get("x", 0) == 0 and m.get("y", 0) == 0:
                    primary = m
                    break
            m = primary or (mons[0] if isinstance(mons[0], dict) else None)
            if not m:
                return 0
            reserved = m.get("reserved") or [0, 0, 0, 0]
            return int(reserved[1] or 0)
        except Exception:
            return 0

    def _layout_px(self, size):
        """Window size in *unscaled* pixels for a given board size."""
        if size <= 60:
            cb = BOARD_COORD_BORDER
            cap = int(size * 0.85) + 20 - 50
            w = 180 + cb + size * 8 + cb + 180
        else:
            cb = BOARD_COORD_BORDER
            cap = int(size * 0.85) + 20
            w = 280 + cb + size * 8 + cb + 280
        h = cap + cb + size * 8 + cb + cap + 4
        return w, h

    def _usable_screen(self):
        """Window limits (window units = physical px): the desktop minus the
        area reserved for the top bar (Omarchy)."""
        try:
            sizes = pygame.display.get_desktop_sizes()
            if not sizes or sizes[0][0] <= 0 or sizes[0][1] <= 0:
                return SCALED_MAX_W, SCALED_MAX_H
            w, h = sizes[0]
        except Exception:
            w, h = SCALED_MAX_W, SCALED_MAX_H
        top = int(round(self._top_reserved() * self._compositor_scale()))
        return w, h - top

    def _fit_size(self, chosen):
        """Greatest predefined size whose window fits below the top bar."""
        limit_w, limit_h = self._usable_screen()
        res = chosen
        for size in SIZES:
            w, h = self._layout_px(size[1])
            if w <= limit_w and h <= limit_h:
                res = size[1]
        return res

    def _clamp_size(self, chosen):
        """Largest square size at or below the chosen value that still fits the
        usable screen (keeps e.g. 'Groot' fully visible on a small display)."""
        limit_w, limit_h = self._usable_screen()
        hi = max(40, min(100, chosen))
        for s in range(hi, 39, -1):
            w, h = self._layout_px(s)
            if w <= limit_w and h <= limit_h:
                return s
        return hi

    def _compute_layout(self, size):
        self.square_size = size
        if size <= 60:
            self.sidebar_width = 180
        else:
            self.sidebar_width = 280
        self.capture_strip = int(size * 0.85) + 20   # vertical room for a row of captured pieces
        if size <= 60:
            self.capture_strip -= 50
        self.board_px = size * 8
        # Center the board in the window: left margin equals the sidebar width on
        # the right, so the board sits exactly in the middle of the window.
        cb = BOARD_COORD_BORDER
        self.board_x = self.sidebar_width + cb
        self.screen_width = self.sidebar_width + cb + self.board_px + cb + self.sidebar_width
        self.screen_height = self.capture_strip + cb + self.board_px + cb + self.capture_strip + 4

    def _apply_display_mode(self):
        if self.fullscreen:
            self.screen = pygame.display.set_mode((0, 0), pygame.FULLSCREEN)
        else:
            self._screen_width = self.screen_width
            self._screen_height = self.screen_height
            self._set_window_pos_centered()
            self.screen = pygame.display.set_mode((self.screen_width, self.screen_height))
            self._set_window_pos_centered()

    def _set_window_pos_centered(self):
        """Place the window centered, in the area below any top bar (Omarchy).

        SDL window coordinates and desktop sizes are in the windowing system's
        X11 units (physical pixels for this display); only the compositor-scale
        reporting (hyprctl) is in logical pixels, so the bar heights are the
        only value that needs scaling here."""
        try:
            sizes = pygame.display.get_desktop_sizes()
            if not sizes or sizes[0][0] <= 0 or sizes[0][1] <= 0:
                return
            dw, dh = sizes[0]
            top = int(round(self._top_reserved() * self._compositor_scale()))
            wx = (dw - self._screen_width) // 2
            avail = dh - top
            wy = top + (avail - self._screen_height) // 2
            if wy < top:
                wy = top  # never slide under the top bar
            pygame.display.set_window_position((max(wx, 0), max(wy, 0)))
        except Exception:
            pass

    def _center_window(self):
        """Center the game window on the desktop."""
        self._set_window_pos_centered()

    def _board_origin(self):
        return (self.board_x, self.capture_strip + BOARD_COORD_BORDER)

    def _screen_to_board(self, screen_row, screen_col):
        """Convert screen grid position to board coordinates."""
        if self.flipped:
            return (7 - screen_row, 7 - screen_col)
        return (screen_row, screen_col)

    def _board_to_screen(self, board_row, board_col):
        """Convert board coordinates to screen grid position."""
        if self.flipped:
            return (7 - board_row, 7 - board_col)
        return (board_row, board_col)

    def _reset_game(self):
        self.board = ChessBoard()
        self.selected_piece = None
        self.valid_moves = []
        self.last_move = None
        self.game_over = False
        self.winner = None
        self.win_reason = None
        self.ai_thinking = False
        self.ai_move = None
        self.flipped = False  # True = board is flipped (human's pieces at bottom)

        # Hint / promotion / sound state for a fresh game
        self.hint_move = None
        self.hint_thinking = False
        self._pending_promotion = None
        self._promo_buttons = []
        self._promo_panel = None
        self._played_game_over_sound = False

        # Undo/redo stacks (board snapshots) + sidebar buttons
        self._undo_stack = []
        self._redo_stack = []
        self.btn_undo = None
        self.btn_redo = None
        self.btn_restart = None
        self.btn_settings = None
        self.btn_hint = None
        self.btn_save = None
        self.btn_slots = None

        # Timer state (seconds)
        self._timer_started = False
        if self.timer_type == "clock":
            secs = self.timer_minutes * 60
            self.timer_white = secs
            self.timer_black = secs
            self.timer_total = None
        elif self.timer_type == "capture":
            self.timer_total = self.timer_minutes * 60
            self.timer_white = self.timer_black = None
        else:
            self.timer_white = self.timer_black = self.timer_total = None

    # ---------------------------------------------------------------- menu
    def _size_label(self, sq):
        """Name of the predefined size closest to the actual square size, so a
        clamped value like 98 (Groot that just fits) still highlights Groot."""
        return min(SIZES, key=lambda item: abs(item[1] - sq))[0]

    def _display_size(self):
        """The drawable area we lay the menu out in: the fullscreen display when
        fullscreen is active, otherwise the windowed layout size."""
        if getattr(self, "_menu_frame", None):
            return self._menu_frame
        if self.fullscreen:
            try:
                w, h = self.screen.get_size()
                if w > 0 and h > 0:
                    return w, h
            except Exception:
                pass
        return self.screen_width, self.screen_height

    def _build_menu(self):
        mw, mh_win = self._display_size()
        cx = mw // 2
        scale = 1.0 + (self.square_size - 60) * 0.009
        if self.square_size <= 60:
            scale = 0.85
        # The menu reads as too large: draw it 5% smaller and cap it to about
        # 82% of the usable window height so it never fills (and never clips).
        scale *= 0.95
        usable_h = mh_win - 16
        scale = min(scale, (usable_h / 692.0) * 0.82)
        scale = max(scale, 0.40)
        # On the smallest window the menu is a bit cramped: make it ~10% bigger.
        if self.square_size <= 60:
            scale *= 1.10
        self._menu_title_pos = None
        self._menu_label_items = []
        self.font_large = pygame.font.Font(None, int(40 * scale))
        self.font_medium = pygame.font.Font(None, int(24 * scale))
        self.font_small = pygame.font.Font(None, int(20 * scale))
        self.font_tiny = pygame.font.Font(None, int(18 * scale))
        bw = int(320 * scale)
        bh = int(42 * scale)
        small_h = int(34 * scale)
        row_gap = max(2, int(4 * scale))
        lbl_gap = int(22 * scale)
        title_gap = int(62 * scale)
        menu_h = int(692 * scale)
        # Vertical placement: large menus sit a little high, small menus a
        # little low, so neither hugs the top of a big window nor the bottom.
        if self.square_size <= 60:
            y = (mh_win - menu_h) // 2 - 20
        else:
            y = (mh_win - menu_h) // 3

        if self.square_size <= 60:
            self._menu_title("PylonChess", cx, y + 25)
        else:
            self._menu_title("PylonChess", cx, y)
        y += title_gap

        # Mode selection (single toggle button)
        mode_label = "Tegen de computer" if self.mode == "ai" else "Twee spelers (PvP)"
        self.btn_mode = Button((cx - bw // 2, y, bw, bh), mode_label, self.font_medium)
        y += bh + row_gap

        # Color / bottom-side selection
        self.btn_ai_side = Button((cx - bw // 2, y, bw, bh),
                                  "Speel als: " + self._side_label(), self.font_medium)
        self.btn_ai_side.active = True
        y += bh + row_gap

        # Difficulty (AI only)
        self._menu_section_label("Niveau computer:", cx, bw, y)
        y += lbl_gap
        dbtn_w = (bw - 20) // 3
        self.btn_diff = {}
        rows_y, group_x = self._place_button_group(self.btn_diff, cx, bw, small_h, DIFFICULTIES,
                                                   [(d, DIFFICULTY_LABELS[d]) for d in DIFFICULTIES],
                                                   dbtn_w, y, self.ai_difficulty)
        y = rows_y
        y += max(2, int(4 * scale))

        # Board size
        self._menu_section_label("Bordgrootte:", cx, bw, y)
        y += lbl_gap
        sbtn_w = (bw - 20) // 3
        self.btn_size = {}
        active_size = self._size_label(self.square_size)
        rows_y, _ = self._place_button_group(self.btn_size, cx, bw, small_h, SIZES,
                                             [(l, l) for l, _ in SIZES], sbtn_w, y, active_size)
        y = rows_y
        y += max(2, int(4 * scale))

        # Timer type
        self._menu_section_label("Timer:", cx, bw, y)
        y += lbl_gap
        tsub_w = (bw - 20) // 3
        self.btn_timer_type = {}
        timer_options = [("Uit", "off"), ("Schaakklok", "clock"), ("Slaan", "capture")]
        rows_y, _ = self._place_button_group(self.btn_timer_type, cx, bw, small_h, timer_options,
                                             [(t, l) for l, t in timer_options], tsub_w, y, self.timer_type)
        y = rows_y
        y += max(2, int(4 * scale))

        # Timer minutes (for the chess clock per player, shared for capture mode)
        self._menu_section_label("Tijd (minuten):", cx, bw, y)
        y += lbl_gap
        min_w = (bw - 20) // 3
        TIMER_MINS = [1, 2, 3, 5, 10, 15, 20, 30, 60]
        self.timer_minutes_options = TIMER_MINS
        self.btn_timer_min = {}
        # Timer minutes: 3 rows × 3 columns
        min_rows = [TIMER_MINS[i:i + 3] for i in range(0, len(TIMER_MINS), 3)]
        for row_mins in min_rows:
            rows_y, _ = self._place_button_group(self.btn_timer_min, cx, bw, small_h, row_mins,
                                                 [(m, str(m)) for m in row_mins], min_w, y, self.timer_minutes)
            y = rows_y + max(1, int(2 * scale))
        y += max(1, int(2 * scale))

        # Fullscreen
        self.btn_fullscreen = Button((cx - bw // 2, y, bw, bh),
                                     "Fullscreen: " + ("Uit" if self.fullscreen else "Aan"),
                                     self.font_medium)
        y += bh + row_gap

        # Sound + continue last game
        self.btn_sound = Button((cx - bw // 2, y, bw, bh),
                                "Geluid: " + ("Aan" if self.sound.enabled else "Uit"),
                                self.font_medium)
        y += bh + row_gap

        self.btn_continue = Button((cx - bw // 2, y, bw, bh), "Verder spelen",
                                   self.font_medium)
        self.btn_continue.active = self._any_slots()
        y += bh + row_gap

        # Speluitleg
        self.btn_rules = Button((cx - bw // 2, y, bw, bh), "Speluitleg", self.font_medium)
        y += bh + row_gap

        # Credits
        self.btn_credits = Button((cx - bw // 2, y, bw, bh), "Credits", self.font_medium)
        y += bh + row_gap

        # Start the selected mode
        self.btn_start = Button((cx - bw // 2, y, bw, bh), "Start spel", self.font_medium)
        y += bh + row_gap

        # Quit
        self.btn_quit = Button((cx - bw // 2, y, bw, bh), "Afsluiten", self.font_medium)

        self.menu_buttons = [
            self.btn_mode, self.btn_ai_side,
        ] + list(self.btn_diff.values()) + list(self.btn_size.values()) + \
            list(self.btn_timer_type.values()) + list(self.btn_timer_min.values()) + [
            self.btn_fullscreen, self.btn_sound, self.btn_continue,
            self.btn_rules, self.btn_credits,
            self.btn_start, self.btn_quit,
        ]

        # Keep focus on an existing button (or none)
        if not (0 <= self.focus_index < len(self.menu_buttons)):
            self.focus_index = 0
        self._apply_focus()

    def _menu_title(self, text, cx, y):
        self._menu_title_pos = (text, cx, y)

    def _menu_section_label(self, text, cx, bw, y):
        self._menu_label_items.append((text, cx - bw // 2, y))

    def _place_button_group(self, target_dict, cx, bw, row_h, key_sequence, label_pairs, btn_w, y, active_key):
        """Layout a row of small buttons so the group is centred within `bw`.
        Returns (new_y, left_x_of_group).  Each entry in `label_pairs` is
        (dict_key, display_text)."""
        step = btn_w + 8
        # centre group: |pad| btn step btn step ... pad|
        n = len(key_sequence)
        group_w = (btn_w - 4) + (n - 1) * (btn_w + 8)
        padding = (bw - group_w) // 2
        left = cx - bw // 2 + max(0, padding)
        for i, (key, label) in enumerate(label_pairs):
            b = Button((left + i * step, y, btn_w - 4, row_h), label, self.font_small)
            b.active = (key == active_key)
            target_dict[key] = b
        return y + row_h, left

    def _side_label(self):
        if self.mode == "ai":
            return "Zwart" if self.ai_side == Color.WHITE else "Wit"
        return "Wit" if self.pvp_bottom == Color.WHITE else "Zwart"

    def _menu_event(self, event):
        # The compositor can change the window size asynchronously (fullscreen
        # transition): rebuild the menu whenever the window is resized so the
        # first click already shows the correct, centered fullscreen menu.
        if event.type == pygame.VIDEORESIZE:
            w, h = getattr(event, "w", 0), getattr(event, "h", 0)
            if (w, h) != (self.screen_width, self.screen_height):
                self._menu_frame = (w, h)
                self._build_menu()
                self._menu_frame = None
            return
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_TAB:
                shift = pygame.key.get_mods() & pygame.KMOD_SHIFT
                self._focus_tab(reverse=bool(shift))
                return
            if event.key in (pygame.K_UP, pygame.K_DOWN):
                self._focus_next(reverse=(event.key == pygame.K_UP))
                return
            if event.key in (pygame.K_LEFT, pygame.K_RIGHT):
                self._focus_row_step(reverse=(event.key == pygame.K_LEFT))
                return
            if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
                if 0 <= self.focus_index < len(self.menu_buttons):
                    self._activate_button(self.menu_buttons[self.focus_index])
                    self._rebuild_if_needed()
                return
        for b in self.menu_buttons:
            if b.handle_event(event):
                self._set_focus_index(self.menu_buttons.index(b))
                self._activate_button(b)
                self._rebuild_if_needed()
                return

    # ---------- focus / keyboard navigation
    def _focus_tab(self, reverse=False):
        """Tab/Shift+Tab: move focus linearly through all buttons."""
        n = len(self.menu_buttons)
        if n == 0:
            return
        step = -1 if reverse else 1
        self.focus_index = (self.focus_index + step) % n
        self._apply_focus()

    def _focus_next(self, reverse=False):
        """Move focus up/down between logical menu rows, preserving column position."""
        if not (0 <= self.focus_index < len(self.menu_buttons)):
            self.focus_index = 0
            self._apply_focus()
            return
        cur = self.menu_buttons[self.focus_index]
        rows = self._menu_rows()
        # Find current row and column within it
        cur_row_idx = None
        cur_col = 0
        for ri, row in enumerate(rows):
            if cur in row:
                cur_row_idx = ri
                cur_col = row.index(cur)
                break
        if cur_row_idx is None:
            # Single button not in a row group — find its row
            for ri, row in enumerate(rows):
                if cur in row:
                    cur_row_idx = ri
                    break
            if cur_row_idx is None:
                cur_row_idx = 0
                cur_col = 0
        # Move to next/prev row
        step = -1 if reverse else 1
        new_row_idx = (cur_row_idx + step) % len(rows)
        new_row = rows[new_row_idx]
        # Keep column position (clamped to row length)
        new_col = min(cur_col, len(new_row) - 1)
        self.focus_index = self.menu_buttons.index(new_row[new_col])
        self._apply_focus()

    def _focus_row_step(self, reverse=False):
        """Move focus left/right within a row of sibling buttons (difficulty, size, timer).
        Falls back to _focus_next if current button has no row siblings."""
        if not (0 <= self.focus_index < len(self.menu_buttons)):
            return
        cur = self.menu_buttons[self.focus_index]
        # Find the row this button belongs to
        for row in self._menu_rows():
            if cur in row:
                idx = row.index(cur)
                step = -1 if reverse else 1
                self.focus_index = self.menu_buttons.index(row[(idx + step) % len(row)])
                self._apply_focus()
                return
        # Not in a row — move vertically
        self._focus_next(reverse=reverse)

    def _menu_rows(self):
        """Return list of rows, where each row is a list of sibling buttons in order.
        Single buttons are wrapped in a one-element list."""
        rows = []
        rows.append([self.btn_mode])
        rows.append([self.btn_ai_side])
        if self.btn_diff:
            rows.append([self.btn_diff[d] for d in DIFFICULTIES if d in self.btn_diff])
        if self.btn_size:
            rows.append([self.btn_size[l] for l, _ in SIZES if l in self.btn_size])
        if self.btn_timer_type:
            rows.append([self.btn_timer_type[t] for t in ["off", "clock", "capture"] if t in self.btn_timer_type])
        if self.btn_timer_min:
            mins = self.timer_minutes_options
            for i in range(0, len(mins), 3):
                rows.append([self.btn_timer_min[m] for m in mins[i:i + 3] if m in self.btn_timer_min])
        rows.append([self.btn_fullscreen])
        rows.append([self.btn_sound])
        rows.append([self.btn_continue])
        rows.append([self.btn_rules])
        rows.append([self.btn_credits])
        rows.append([self.btn_start])
        rows.append([self.btn_quit])
        return rows

    def _set_focus_index(self, index):
        self.focus_index = index
        self._apply_focus()

    def _apply_focus(self):
        for i, b in enumerate(self.menu_buttons):
            b.focused = (i == self.focus_index)

    # ---------- button activation
    def _activate_button(self, b):
        self._menu_notice = None
        if b is self.btn_mode:
            self.mode = "pvp" if self.mode == "ai" else "ai"
        elif b is self.btn_ai_side:
            if self.mode == "ai":
                self.ai_side = Color.BLACK if self.ai_side == Color.WHITE else Color.WHITE
            else:
                self.pvp_bottom = Color.WHITE if self.pvp_bottom == Color.BLACK else Color.BLACK
        elif b is self.btn_start:
            self.start_game(self.mode)
        elif b in self.btn_diff.values():
            if self.mode == "ai":
                for diff, bb in self.btn_diff.items():
                    bb.active = (bb is b)
                self.ai_difficulty = next(d for d, bb in self.btn_diff.items() if bb is b)
        elif b in self.btn_size.values():
            for l, size in SIZES:
                if l == b.text:
                    self.square_size = self._clamp_size(size)
                    break
            self._compute_layout(self.square_size)
            if not self.fullscreen:
                self._apply_display_mode()
            for l, bb in self.btn_size.items():
                bb.active = (l == b.text)
        elif b in self.btn_timer_type.values():
            for tv, bb in self.btn_timer_type.items():
                bb.active = (bb is b)
            self.timer_type = next(t for t, bb in self.btn_timer_type.items() if bb is b)
        elif b in self.btn_timer_min.values():
            for m, bb in self.btn_timer_min.items():
                bb.active = (bb is b)
            self.timer_minutes = next(m for m, bb in self.btn_timer_min.items() if bb is b)
        elif b is self.btn_fullscreen:
            self.fullscreen = not self.fullscreen
            self._apply_display_mode()
            self._build_menu()
        elif b is self.btn_sound:
            self.sound.toggle()
        elif b is self.btn_continue:
            self._open_slot_overlay("load")
        elif b is self.btn_rules:
            self.state = "rules"
        elif b is self.btn_credits:
            self.state = "credits"
        elif b is self.btn_quit:
            pygame.quit()
            raise SystemExit

    def _rebuild_if_needed(self):
        self._build_menu()


    # ---------------------------------------------------------------- game start
    def start_game(self, mode):
        self._notice = None
        self.mode = mode
        self.ai.set_difficulty(self.ai_difficulty)
        self.ai.reset()
        self.state = "game"

        # Preserve the human-selected side from the menu (ai_side = AI color)
        if mode == "ai":
            ai_color = self.ai_side
        else:
            pvp_bottom = self.pvp_bottom
        self._reset_game()  # resets ai_side to BLACK
        self.mode = mode
        if mode == "ai":
            self.ai_side = ai_color  # restore the AI color chosen in menu
            # The standard board has White on rows 0-1 (top). Humans expect their
            # own pieces at the bottom, so flip when the human plays White.
            # ai_side == BLACK means the human plays White -> flip.
            self.flipped = (self.ai_side == Color.BLACK)
            # If AI plays White and it's White's turn, AI moves first
            if self.ai_side == Color.WHITE:
                self._request_ai_move()
        else:
            # PvP: the chosen color goes at the bottom of the board
            self.pvp_bottom = pvp_bottom
            self.flipped = (self.pvp_bottom == Color.WHITE)

        # Center the window in the area below the top bar when the game begins.
        if not self.fullscreen:
            self._set_window_pos_centered()

    # ---------------------------------------------------------------- undoredo
    def _push_undo(self):
        """Record the board state before a move is applied."""
        self._undo_stack.append(self.board.snapshot())
        self._redo_stack.clear()

    def _undo(self):
        if self.ai_thinking:
            return
        if not self._undo_stack:
            return
        n = 2 if self.mode == "ai" else 1
        if self.mode == "ai" and len(self._undo_stack) < 2:
            return   # only the AI's opening move exists -- nothing to take back yet
        for _ in range(n):
            if not self._undo_stack:
                break
            self._redo_stack.append(self.board.snapshot())
            self.board.restore(self._undo_stack.pop())
        self._after_undo_redo()

    def _redo(self):
        if self.ai_thinking:
            return
        if not self._redo_stack:
            return
        n = 2 if self.mode == "ai" else 1
        for _ in range(n):
            if not self._redo_stack:
                break
            self._undo_stack.append(self.board.snapshot())
            self.board.restore(self._redo_stack.pop())
        self._after_undo_redo()

    def _after_undo_redo(self):
        self.selected_piece = None
        self.valid_moves = []
        self.hint_move = None
        self._played_game_over_sound = False
        self.game_over = False
        self.winner = None
        self.win_reason = None
        if self.board.move_history:
            m = self.board.move_history[-1]
            self.last_move = (m['from'], m['to'])
        else:
            self.last_move = None
        self._check_game_over()

    # ---------------------------------------------------------------- game event
    def _game_event(self, event):
        if self._pending_promotion:
            self._promotion_event(event)
            return
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_u:
                self._undo()
                return
            if event.key == pygame.K_y:
                self._redo()
                return
            if event.key == pygame.K_r:
                self.start_game(self.mode)
                return
            if event.key == pygame.K_f:
                self.fullscreen = not self.fullscreen
                self._apply_display_mode()
                return
            if event.key == pygame.K_h:
                self._request_hint()
                return
            if event.key == pygame.K_m:
                self.sound.toggle()
                self._set_notice("Geluid: " + ("aan" if self.sound.enabled else "uit"),
                                 seconds=2.0)
                return
            if event.key == pygame.K_s:
                self._open_slot_overlay("save")
                return
            if event.key == pygame.K_l:
                self._open_slot_overlay("load")
                return
            if event.key == pygame.K_p:
                self._export_pgn()
                return
            if event.key == pygame.K_ESCAPE:
                self.state = "menu"
                self._build_menu()
                return
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            if self.btn_restart and self.btn_restart.rect.collidepoint(event.pos):
                self.btn_restart.press()
                self.start_game(self.mode)
                return
            if self.btn_settings and self.btn_settings.rect.collidepoint(event.pos):
                self.btn_settings.press()
                self.state = "menu"
                self._build_menu()
                return
            if self.btn_hint and self.btn_hint.rect.collidepoint(event.pos):
                self.btn_hint.press()
                self._request_hint()
                return
            if self.btn_undo and self.btn_undo.rect.collidepoint(event.pos):
                self.btn_undo.press()
                self._undo()
                return
            if self.btn_redo and self.btn_redo.rect.collidepoint(event.pos):
                self.btn_redo.press()
                self._redo()
                return
            if self.btn_save and self.btn_save.rect.collidepoint(event.pos):
                self.btn_save.press()
                self._open_slot_overlay("save")
                return
            if self.btn_slots and self.btn_slots.rect.collidepoint(event.pos):
                self.btn_slots.press()
                self._open_slot_overlay("load")
                return
            self.handle_click(event.pos)

    # ---------------------------------------------------------------- clicks
    def handle_click(self, pos):
        if self.game_over or self.ai_thinking:
            return
        # In AI mode, ignore clicks if it's AI's turn
        if self.mode == "ai" and self.board.current_turn == self.ai_side:
            return

        ox, oy = self._board_origin()
        x, y = pos
        # map to board square
        if not (ox <= x < ox + self.board_px and oy <= y < oy + self.board_px):
            return
        screen_col = (x - ox) // self.square_size
        screen_row = (y - oy) // self.square_size
        row, col = self._screen_to_board(screen_row, screen_col)
        if not self.board.is_valid_position(row, col):
            return

        if self.selected_piece:
            from_row, from_col = self.selected_piece
            if (row, col) in self.valid_moves:
                if self._promotion_move(from_row, from_col, row, col):
                    self._open_promotion(from_row, from_col, row, col)
                    return
                self._do_move(from_row, from_col, row, col)
                return
            # Clicking the same piece again deselects it
            if (row, col) == self.selected_piece:
                self.selected_piece = None
                self.valid_moves = []
                return
            # try selecting a different own piece
            piece = self.board.get_piece(row, col)
            if piece and piece.color == self.board.current_turn:
                self.selected_piece = (row, col)
                self.valid_moves = self.board.get_valid_moves(row, col)
            else:
                self.selected_piece = None
                self.valid_moves = []
        else:
            piece = self.board.get_piece(row, col)
            if piece and piece.color == self.board.current_turn:
                self.selected_piece = (row, col)
                self.valid_moves = self.board.get_valid_moves(row, col)

    # ---------------------------------------------------------------- moves
    def _promotion_move(self, fr, fc, tr, tc):
        """True if the pawn move lands on the promotion rank."""
        piece = self.board.get_piece(fr, fc)
        if not piece or piece.piece_type != PieceType.PAWN:
            return False
        return (piece.color == Color.WHITE and tr == 7) or \
               (piece.color == Color.BLACK and tr == 0)

    def _do_move(self, fr, fc, tr, tc, promotion=None):
        """Apply a move (with optional promotion), update state and side songs."""
        before = self.board.snapshot()
        if not self.board.make_move(fr, fc, tr, tc, promotion=promotion):
            return False
        self._undo_stack.append(before)
        self._redo_stack.clear()
        self.last_move = ((fr, fc), (tr, tc))
        self.selected_piece = None
        self.valid_moves = []
        self.hint_move = None
        self._timer_mark_move()
        self._play_move_sound()
        self._check_game_over()
        if self.game_over:
            self._play_game_over()
        self._after_move()
        return True

    def _play_move_sound(self):
        if not self.board.move_history:
            return
        m = self.board.move_history[-1]
        san = m.get("san", "")
        if "=" in san:
            self.sound.play("promote")
        elif m.get("is_castle"):
            self.sound.play("castle")
        elif m.get("captured"):
            self.sound.play("capture")
        elif san.endswith("+") or san.endswith("#"):
            self.sound.play("check")
        else:
            self.sound.play("move")

    def _play_game_over(self):
        """Play the end-of-game sound exactly once."""
        if not self._played_game_over_sound:
            self._played_game_over_sound = True
            self.sound.play("game_over")

    # ---------------------------------------------------------------- promotion picker
    def _open_promotion(self, fr, fc, tr, tc):
        self._pending_promotion = (fr, fc, tr, tc, self.board.current_turn)
        slot, gap = 52, 10
        pad = 18
        title_h = 26
        label_h = 16
        panel_w = 2 * pad + 4 * slot + 3 * gap
        panel_h = pad + title_h + slot + label_h + pad + 6
        cx = self.screen_width // 2
        cy = self.screen_height // 2
        px, py = cx - panel_w // 2, cy - panel_h // 2
        self._promo_panel = pygame.Rect(px, py, panel_w, panel_h)
        self._promo_buttons = []
        for i, pt in enumerate((PieceType.QUEEN, PieceType.ROOK,
                                PieceType.BISHOP, PieceType.KNIGHT)):
            x = px + pad + i * (slot + gap)
            y = py + pad + title_h
            self._promo_buttons.append((pygame.Rect(x, y, slot, slot), pt))

    def _cancel_promotion(self):
        self._pending_promotion = None
        self._promo_buttons = []
        self.selected_piece = None
        self.valid_moves = []

    def _choose_promotion(self, ptype):
        fr, fc, tr, tc, _ = self._pending_promotion
        self._pending_promotion = None
        self._promo_buttons = []
        self._do_move(fr, fc, tr, tc, promotion=ptype)

    def _promotion_event(self, event):
        if event.type == pygame.KEYDOWN:
            if event.key in (pygame.K_ESCAPE,):
                self._cancel_promotion()
                return
            key_map = {
                pygame.K_1: PieceType.QUEEN, pygame.K_2: PieceType.ROOK,
                pygame.K_3: PieceType.BISHOP, pygame.K_4: PieceType.KNIGHT,
                pygame.K_q: PieceType.QUEEN, pygame.K_r: PieceType.ROOK,
                pygame.K_b: PieceType.BISHOP, pygame.K_n: PieceType.KNIGHT,
                pygame.K_RETURN: PieceType.QUEEN,
                pygame.K_KP_ENTER: PieceType.QUEEN,
                pygame.K_SPACE: PieceType.QUEEN,
            }
            if event.key in key_map:
                self._choose_promotion(key_map[event.key])
            return
        if event.type == pygame.MOUSEBUTTONDOWN:
            for rect, pt in self._promo_buttons:
                if rect.collidepoint(event.pos):
                    self._choose_promotion(pt)
                    return
            if self._promo_panel and not self._promo_panel.collidepoint(event.pos):
                self._cancel_promotion()
            elif event.button == 3:
                self._cancel_promotion()

    def _draw_promotion_picker(self):
        overlay = pygame.Surface((self.screen_width, self.screen_height), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 160))
        self.screen.blit(overlay, (0, 0))

        panel = self._promo_panel
        pygame.draw.rect(self.screen, PANEL, panel, border_radius=12)
        pygame.draw.rect(self.screen, BUTTON, panel, 2, border_radius=12)

        title = self.font_medium.render("Promotie: kies een stuk", True, WHITE)
        self.screen.blit(title, title.get_rect(center=(panel.centerx, panel.y + 20)))

        color = self._pending_promotion[4]
        mouse = pygame.mouse.get_pos()
        labels = {PieceType.QUEEN: "Dame", PieceType.ROOK: "Toren",
                  PieceType.BISHOP: "Loper", PieceType.KNIGHT: "Paard"}
        for rect, pt in self._promo_buttons:
            hover = rect.collidepoint(mouse)
            pygame.draw.rect(self.screen, (50, 50, 50), rect, border_radius=8)
            pygame.draw.rect(self.screen, FOCUS_COLOR if hover else (110, 110, 110),
                             rect, 2, border_radius=8)
            self._draw_piece_shape(pt, color, rect.centerx, rect.centery - 4,
                                   rect.height * 0.7)
            lab = self.font_tiny.render(labels[pt], True, FOCUS_COLOR if hover else WHITE)
            self.screen.blit(lab, lab.get_rect(center=(rect.centerx, rect.bottom + 9)))

    # ---------------------------------------------------------------- hint
    def _request_hint(self):
        if self.hint_thinking or self.game_over or self._pending_promotion:
            return
        if self.mode == "ai" and self.board.current_turn == self.ai_side:
            return
        self.hint_thinking = True
        board = self.board.clone()
        t = threading.Thread(target=self._hint_worker, args=(board,), daemon=True)
        t.start()

    def _hint_worker(self, board):
        try:
            difficulty = self.ai_difficulty
            if difficulty == "easy":
                difficulty = "medium"
            ai = self._hint_ai
            ai.reset()
            ai.set_difficulty(difficulty)
            move = ai.choose_move(board)
            if move is None:
                return
            # Only publish the hint if the position hasn't changed meanwhile.
            if self.board.current_turn == board.current_turn:
                self.hint_move = move
                self.sound.play("hint")
        finally:
            self.hint_thinking = False

    # ---------------------------------------------------------------- save / load / PGN
    NUM_SLOTS = 20

    def _slot_dir(self):
        return os.path.join(os.path.expanduser("~"), "PylonChess", "saves")

    def _slot_path(self, n):
        return os.path.join(self._slot_dir(), f"slot{n}.json")

    def _game_save_data(self):
        return {
            "fen": self.board.to_fen(),
            "moves": [
                {
                    "from": [m["from"][0], m["from"][1]],
                    "to": [m["to"][0], m["to"][1]],
                    "san": m.get("san", ""),
                    "is_castle": bool(m.get("is_castle")),
                    "captured": bool(m.get("captured")),
                    "promotion": m.get("promotion").name if m.get("promotion") else None,
                }
                for m in self.board.move_history
            ],
            "mode": self.mode,
            "ai_side": "white" if self.ai_side == Color.WHITE else "black",
            "pvp_bottom": "white" if self.pvp_bottom == Color.WHITE else "black",
            "difficulty": self.ai_difficulty,
            "timer_type": self.timer_type,
            "timer_minutes": self.timer_minutes,
            "timer_white": self.timer_white,
            "timer_black": self.timer_black,
            "timer_total": self.timer_total,
            "fullscreen": self.fullscreen,
            "square_size": self.square_size,
            "sound_enabled": self.sound.enabled,
            "saved_at": time.strftime("%Y-%m-%d %H:%M"),
        }

    def _slot_label(self, data):
        """Short human-readable summary shown in the slot chooser."""
        mode = "Computer" if data.get("mode", "ai") == "ai" else "2 spelers"
        white = data.get("white_name") or ("Computer" if data.get("mode", "ai") == "ai"
                                           and data.get("ai_side") == "white" else "Wit")
        black = data.get("black_name") or ("Computer" if data.get("mode", "ai") == "ai"
                                           and data.get("ai_side") == "black" else "Zwart")
        moves = data.get("move_count", 0)
        line1 = f"{white} vs {black}"
        line2 = f"{moves} zetten" if moves else ""
        return line1, line2

    def _save_game_to_slot(self, n):
        if not (1 <= n <= self.NUM_SLOTS):
            return
        data = self._game_save_data()
        data["move_count"] = len(self.board.move_history)
        try:
            os.makedirs(self._slot_dir(), exist_ok=True)
            with open(self._slot_path(n), "w") as f:
                json.dump(data, f)
            self._set_notice(f"Opgeslagen in slot {n}.", seconds=3.0)
        except OSError:
            self._set_notice("Opslaan mislukt.", seconds=3.0)

    def _load_game_from_slot(self, n):
        if not (1 <= n <= self.NUM_SLOTS):
            return
        path = self._slot_path(n)
        if not os.path.exists(path):
            self._set_notice(f"Slot {n} is leeg.", seconds=3.0)
            return
        try:
            with open(path) as f:
                data = json.load(f)
        except (OSError, ValueError):
            self._set_notice(f"Slot {n} onleesbaar.", seconds=3.0)
            return
        self._apply_save(data, slot=n)

    def _slot_summary(self, n):
        """(occupied, labels) for slot n; labels is (line1, line2) tuple."""
        path = self._slot_path(n)
        if not os.path.exists(path):
            return False, ("", "")
        try:
            with open(path) as f:
                data = json.load(f)
            return True, self._slot_label(data)
        except (OSError, ValueError):
            return True, ("(beschadigd)", "")

    def _any_slots(self):
        for n in range(1, self.NUM_SLOTS + 1):
            if os.path.exists(self._slot_path(n)):
                return True
        return False

    # ------------------------------------------------------------ slot overlay
    def _open_slot_overlay(self, mode):
        self._slot_mode = mode          # "save", "load" or "delete"
        self._slot_return = self.state  # "menu" or "game"
        self._build_slot_overlay()
        self.state = "slots"

    def _slot_title_text(self, mode):
        return {"save": "Opslaan: kies een slot",
                "load": "Laden: kies een slot",
                "delete": "Verwijderen: kies een slot"}.get(mode, "Slots")

    def _build_slot_overlay(self):
        cols, rows = 4, 5
        pad, gap = 26, 8
        title_h, tab_h, notice_h, btn_h = 34, 30, 40, 44
        avail_w = self.screen_width - 2 * pad - (cols - 1) * gap
        btn_w = min(220, avail_w // cols)
        panel_w = 2 * pad + cols * btn_w + (cols - 1) * gap
        panel_h = (pad + title_h + 8 + tab_h + 6 +
                   rows * btn_h + (rows - 1) * gap + notice_h + pad)
        cx = self.screen_width // 2
        cy = self.screen_height // 2
        px, py = cx - panel_w // 2, cy - panel_h // 2
        self._slot_panel = pygame.Rect(px, py, panel_w, panel_h)
        self._slot_pad = pad
        self._slot_title = self._slot_title_text(self._slot_mode)

        # Mode tabs (Opslaan / Laden / Verwijderen)
        tab_labels = [("Opslaan", "save"), ("Laden", "load"), ("Verwijderen", "delete")]
        tab_w = 110
        total = len(tab_labels) * tab_w + (len(tab_labels) - 1) * 8
        ty = py + pad + title_h + 8
        start_x = cx - total // 2
        self._slot_tabs = []
        for i, (label, mode) in enumerate(tab_labels):
            x = start_x + i * (tab_w + 8)
            self._slot_tabs.append((pygame.Rect(x, ty, tab_w, tab_h), mode))

        # Slot grid
        self._slot_buttons = []
        for i in range(self.NUM_SLOTS):
            n = i + 1
            r, c = divmod(i, cols)
            x = px + pad + c * (btn_w + gap)
            y = py + pad + title_h + 8 + tab_h + 6 + r * (btn_h + gap)
            occupied, label = self._slot_summary(n)
            self._slot_buttons.append(
                (pygame.Rect(x, y, btn_w - 6, btn_h), n, occupied, label))

        # Bottom row: Annuleren (right) + footer hint (left)
        cw, ch = 120, 30
        self._slot_cancel_rect = pygame.Rect(px + panel_w - pad - cw,
                                             py + panel_h - pad - ch, cw, ch)
        self._slot_confirm = None
        self._slot_confirm_yes = None
        self._slot_confirm_no = None
        if self._slot_mode == "load":
            for idx, (_, n, occ, _) in enumerate(self._slot_buttons):
                if occ:
                    self._slot_focus = idx
                    break
            else:
                self._slot_focus = 0
        else:
            self._slot_focus = 0

    def _close_slot_overlay(self):
        self._finish_slot_overlay()

    def _finish_slot_overlay(self, notice=None):
        ret = self._slot_return
        self._slot_mode = None
        self._slot_return = None
        self._slot_buttons = []
        self._slot_tabs = []
        self._slot_panel = None
        self._slot_confirm = None
        self._slot_confirm_yes = None
        self._slot_confirm_no = None
        if ret == "game":
            self.state = "game"
            if notice:
                self._set_notice(notice, seconds=3.0)
        else:
            self.state = "menu"
            if notice:
                self._menu_notice = notice
            self._build_menu()

    def _switch_slot_mode(self, mode):
        if mode not in ("save", "load", "delete"):
            return
        self._slot_mode = mode
        self._slot_title = self._slot_title_text(mode)
        self._slot_confirm = None
        self._slot_confirm_yes = None
        self._slot_confirm_no = None
        if mode == "load":
            for idx, (_, n, occ, _) in enumerate(self._slot_buttons):
                if occ:
                    self._slot_focus = idx
                    break
            else:
                self._slot_focus = 0
        else:
            self._slot_focus = 0

    def _activate_slot(self, n):
        if not (1 <= n <= self.NUM_SLOTS):
            return
        mode = self._slot_mode
        if mode == "save":
            self._save_game_to_slot(n)
            self._finish_slot_overlay(f"Opgeslagen in slot {n}.")
        elif mode == "load":
            occupied, _ = self._slot_summary(n)
            if not occupied:
                return
            self._load_game_from_slot(n)
            self._finish_slot_overlay()
        elif mode == "delete":
            occupied, _ = self._slot_summary(n)
            if not occupied:
                return
            self._build_slot_confirm(n)

    def _build_slot_confirm(self, n):
        """Show 'Slot n verwijderen?' confirmation inside the panel."""
        self._slot_confirm = n
        panel = self._slot_panel
        cw, ch, bw = 340, 110, 110
        cx = panel.centerx - cw // 2
        cy = panel.centery - ch // 2
        self._slot_confirm_rect = pygame.Rect(cx, cy, cw, ch)
        self._slot_confirm_yes = pygame.Rect(cx + cw - 2 * bw - 30, cy + ch - 40, bw, 28)
        self._slot_confirm_no = pygame.Rect(cx + cw - bw - 15, cy + ch - 40, bw, 28)

    def _confirm_delete(self):
        n = self._slot_confirm
        if n is None:
            return
        try:
            os.remove(self._slot_path(n))
        except OSError:
            pass
        self._finish_slot_overlay(f"Slot {n} verwijderd.")

    def _slot_event(self, event):
        if self._slot_confirm is not None:
            self._slot_confirm_event(event)
            return
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_ESCAPE:
                self._close_slot_overlay()
                return
            cols = 4
            moves = {
                pygame.K_LEFT: -1,
                pygame.K_RIGHT: 1,
                pygame.K_UP: -cols,
                pygame.K_DOWN: cols,
            }
            if event.key in moves:
                self._slot_focus = (self._slot_focus + moves[event.key]) % self.NUM_SLOTS
                return
            if event.key == pygame.K_TAB:
                self._slot_focus = (self._slot_focus + 1) % self.NUM_SLOTS
                return
            if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
                self._activate_slot(self._slot_focus + 1)
                return
            return
        if event.type == pygame.MOUSEBUTTONDOWN:
            if event.button == 3:
                self._close_slot_overlay()
                return
            if event.button == 1:
                for rect, mode in self._slot_tabs:
                    if rect.collidepoint(event.pos):
                        self._switch_slot_mode(mode)
                        return
                for rect, n, occ, _ in self._slot_buttons:
                    if rect.collidepoint(event.pos):
                        self._slot_focus = n - 1
                        self._activate_slot(n)
                        return
                if self._slot_cancel_rect and self._slot_cancel_rect.collidepoint(event.pos):
                    self._close_slot_overlay()
                    return
                if self._slot_panel and not self._slot_panel.collidepoint(event.pos):
                    self._close_slot_overlay()
                    return

    def _slot_confirm_event(self, event):
        if event.type == pygame.KEYDOWN:
            if event.key in (pygame.K_ESCAPE, pygame.K_n):
                self._slot_confirm = None
                self._slot_confirm_yes = None
                self._slot_confirm_no = None
                return
            if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER,
                             pygame.K_SPACE, pygame.K_y):
                self._confirm_delete()
            return
        if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            if self._slot_confirm_yes and self._slot_confirm_yes.collidepoint(event.pos):
                self._confirm_delete()
            elif self._slot_confirm_no and self._slot_confirm_no.collidepoint(event.pos):
                self._slot_confirm = None
                self._slot_confirm_yes = None
                self._slot_confirm_no = None

    def _draw_slots_overlay(self):
        overlay = pygame.Surface((self.screen_width, self.screen_height), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 160))
        self.screen.blit(overlay, (0, 0))

        panel = self._slot_panel
        pygame.draw.rect(self.screen, PANEL, panel, border_radius=12)
        pygame.draw.rect(self.screen, BUTTON, panel, 2, border_radius=12)

        title = self.font_medium.render(self._slot_title, True, WHITE)
        self.screen.blit(title, title.get_rect(center=(panel.centerx, panel.y + 17)))

        mouse = pygame.mouse.get_pos()

        # Mode tabs
        for rect, mode in self._slot_tabs:
            active = (mode == self._slot_mode)
            hover = rect.collidepoint(mouse)
            base = (110, 140, 200) if active else (55, 55, 55)
            if hover and not active:
                base = (75, 75, 75)
            border = FOCUS_COLOR if active else (110, 110, 110)
            pygame.draw.rect(self.screen, base, rect, border_radius=8)
            pygame.draw.rect(self.screen, border, rect, 2, border_radius=8)
            t = self.font_tiny.render(mode, True, WHITE)
            self.screen.blit(t, t.get_rect(center=rect.center))

        # Slot grid
        for i, (rect, n, occupied, labels) in enumerate(self._slot_buttons):
            focused = (i == self._slot_focus)
            hover = rect.collidepoint(mouse)
            if not occupied:
                base = (45, 45, 45)
                border = (80, 80, 80)
                text_c = GRAY
            else:
                if self._slot_mode == "delete":
                    base = (150, 70, 70)
                    border = (180, 110, 110)
                elif self._slot_mode == "save":
                    base = (60, 110, 60)
                    border = (130, 130, 130)
                else:
                    base = (70, 90, 150)
                    border = (130, 130, 130)
                text_c = WHITE
            if focused:
                border = FOCUS_COLOR
            elif hover and occupied:
                border = FOCUS_COLOR
            pygame.draw.rect(self.screen, base, rect, border_radius=8)
            pygame.draw.rect(self.screen, border, rect, 2, border_radius=8)
            num_t = self.font_tiny.render(str(n), True, text_c)
            self.screen.blit(num_t, (rect.x + 8, rect.centery - num_t.get_height() // 2))
            if occupied:
                line1, line2 = labels
                line1_t = self.font_tiny.render(line1, True, text_c)
                line2_t = self.font_tiny.render(line2, True, text_c) if line2 else None
                if line2_t:
                    total_h = line1_t.get_height() + line2_t.get_height()
                    y1 = rect.centery - total_h // 2 + 9
                    self.screen.blit(line1_t, line1_t.get_rect(midleft=(rect.x + 34, y1)))
                    self.screen.blit(line2_t, line2_t.get_rect(midleft=(rect.x + 34, y1 + line1_t.get_height())))
                else:
                    self.screen.blit(line1_t, line1_t.get_rect(midleft=(rect.x + 34, rect.centery + 9)))
            else:
                body_t = self.font_tiny.render("Leeg", True, text_c)
                self.screen.blit(body_t, body_t.get_rect(midleft=(rect.x + 34, rect.centery + 9)))

        # Cancel + footer hint
        crect = self._slot_cancel_rect
        hover = crect.collidepoint(mouse)
        base = (110, 110, 110) if hover else (85, 85, 85)
        pygame.draw.rect(self.screen, base, crect, border_radius=6)
        ctext = self.font_tiny.render("Annuleren", True, WHITE)
        self.screen.blit(ctext, ctext.get_rect(center=crect.center))

        foot = self.font_tiny.render("Pijltjes / Tab: kiezen, Enter: bevestigen, Esc: sluiten",
                                     True, GRAY)
        self.screen.blit(foot, (panel.x + self._slot_pad + 8, panel.bottom - self._slot_pad - 24))

        # Delete confirmation dialog on top
        if self._slot_confirm is not None:
            d = self._slot_confirm_rect
            pygame.draw.rect(self.screen, (30, 30, 30), d, border_radius=10)
            pygame.draw.rect(self.screen, CHECK_COLOR, d, 2, border_radius=10)
            msg = self.font_medium.render(f"Slot {self._slot_confirm} verwijderen?",
                                          True, WHITE)
            self.screen.blit(msg, msg.get_rect(center=(d.centerx, d.y + 22)))
            for rect, label in ((self._slot_confirm_yes, "Ja"),
                                (self._slot_confirm_no, "Nee")):
                hov = rect.collidepoint(mouse)
                cb = (90, 160, 90) if rect is self._slot_confirm_yes else (140, 70, 70)
                cb = (cb[0] + 30, cb[1] + 30, cb[2] + 30) if hov else cb
                pygame.draw.rect(self.screen, cb, rect, border_radius=6)
                pygame.draw.rect(self.screen, WHITE, rect, 1, border_radius=6)
                t = self.font_tiny.render(label, True, WHITE)
                self.screen.blit(t, t.get_rect(center=rect.center))

    def _migrate_legacy_save(self):
        """Move the old single-slot ~/.pylonchess_save.json into slot 1 once."""
        old = os.path.join(os.path.expanduser("~"), ".pylonchess_save.json")
        new = self._slot_path(1)
        if not os.path.exists(old) or os.path.exists(new):
            return
        try:
            with open(old) as f:
                data = json.load(f)
            os.makedirs(self._slot_dir(), exist_ok=True)
            with open(new, "w") as f:
                json.dump(data, f)
            os.remove(old)
        except (OSError, ValueError):
            pass

    def _restore_move_history(self, data):
        """Rebuild the sidebar's 'Zetgeschiedenis' from the saved move list.

        The move records only need to be display/sound compatible (san, from,
        to, is_castle, captured flag), so they are reconstructed directly from
        the saved data instead of being replayed on the board.
        """
        moves = data.get("moves")
        if not moves:
            return
        try:
            history = []
            for mv in moves:
                history.append({
                    "from": (mv["from"][0], mv["from"][1]),
                    "to": (mv["to"][0], mv["to"][1]),
                    "san": mv.get("san", ""),
                    "is_castle": bool(mv.get("is_castle")),
                    "captured": bool(mv.get("captured")),
                    "promotion": (PieceType[mv["promotion"]]
                                  if mv.get("promotion") else None),
                })
            self.board.move_history = history
        except (ValueError, IndexError, TypeError, KeyError):
            return

    def _apply_save(self, data, slot=None):
        self.fullscreen = bool(data.get("fullscreen", False))
        self.square_size = int(data.get("square_size", 80))
        self._compute_layout(self.square_size)
        if not self.fullscreen:
            self._apply_display_mode()
        self.ai_difficulty = data.get("difficulty", "medium")
        self.mode = data.get("mode", "ai")
        self.ai_side = Color.WHITE if data.get("ai_side") == "white" else Color.BLACK
        self.pvp_bottom = Color.WHITE if data.get("pvp_bottom") == "white" else Color.BLACK
        timer_type = data.get("timer_type", "off")
        self.timer_type = timer_type if timer_type in ("off", "clock", "capture") else "off"
        self.timer_minutes = int(data.get("timer_minutes", 10))
        self.ai.set_difficulty(self.ai_difficulty)
        self.ai.reset()
        fen = data.get("fen", "")
        self._reset_game()
        try:
            self.board.load_fen(fen)
        except (ValueError, IndexError):
            self.state = "menu"
            self._build_menu()
            self._menu_notice = "Opgeslagen stelling ongeldig."
            return
        self._restore_move_history(data)
        self.state = "game"
        self._timer_started = True
        self.flipped = (self.ai_side == Color.BLACK) if self.mode == "ai" \
            else (self.pvp_bottom == Color.WHITE)
        if self.timer_type == "clock":
            self.timer_white = max(0, int(data.get("timer_white", self.timer_minutes * 60)))
            self.timer_black = max(0, int(data.get("timer_black", self.timer_minutes * 60)))
        elif self.timer_type == "capture":
            self.timer_total = max(0, int(data.get("timer_total", self.timer_minutes * 60)))
        if data.get("sound_enabled") is not None:
            self.sound.set_enabled(bool(data["sound_enabled"]))
        self._check_game_over()
        if self._notice is None:
            self._set_notice(f"Slot {slot} geladen." if slot else "Spel geladen.",
                             seconds=3.0)
        if self.mode == "ai" and not self.game_over and \
                self.board.current_turn == self.ai_side:
            self._request_ai_move()

    def _export_pgn(self):
        if self.game_over:
            result = {"Wit": "1-0", "Zwart": "0-1"}.get(self.winner, "1/2-1/2")
        else:
            result = "*"
        white, black = "Speler (Wit)", "Speler (Zwart)"
        if self.mode == "ai":
            if self.ai_side == Color.BLACK:
                white, black = "Speler", "Computer"
            else:
                white, black = "Computer", "Speler"
        date = time.strftime("%Y.%m.%d")
        move_time = time.strftime("%H:%M:%S")
        head = [f'[{k} "{v}"]' for k, v in (
            ("Event", "PylonChess partij"), ("Site", "PylonChess"),
            ("Date", date), ("Round", "-"), ("White", white), ("Black", black),
            ("Result", result))]
        san = [m.get("san", self._move_str(m)) for m in self.board.move_history]
        tokens = []
        for i, s in enumerate(san):
            if i % 2 == 0:
                tokens.append(f"{i // 2 + 1}.{s}")
            else:
                tokens.append(s)
        text = " ".join(tokens) + (" " + result if tokens else result)
        folder = os.path.join(os.path.expanduser("~"), "PylonChess")
        path = os.path.join(folder,
                            "pylonchess_" + time.strftime("%Y%m%d_%H%M%S") + ".pgn")
        try:
            os.makedirs(folder, exist_ok=True)
            with open(path, "w") as f:
                f.write("\n".join(head) + "\n\n" + text + "\n")
            self._set_notice("PGN opgeslagen: " + os.path.basename(path), seconds=4.0)
        except OSError:
            self._set_notice("PGN opslaan mislukt.", seconds=3.0)

    def _set_notice(self, text, seconds=4.0):
        self._notice = (text, time.time() + seconds)

    def _after_move(self):
        # After a human move, if playing vs AI and it's AI's turn, request AI move
        if (self.mode == "ai" and not self.game_over and
                self.board.current_turn == self.ai_side):
            self._request_ai_move()

    def _check_game_over(self):
        if self.board.is_checkmate(self.board.current_turn):
            self.game_over = True
            winner = "Black" if self.board.current_turn == Color.WHITE else "White"
            self.winner = "Zwart" if winner == "Black" else "Wit"
            self.win_reason = "schaakmat"
        elif self.board.is_stalemate(self.board.current_turn):
            self.game_over = True
            self.winner = None
            self.win_reason = "pat (remise)"
        elif self.board.is_fifty_move_draw():
            self.game_over = True
            self.winner = None
            self.win_reason = "vijftig zetten zonder slaan of pionzet (remise)"
        elif self.board.is_threefold_repetition():
            self.game_over = True
            self.winner = None
            self.win_reason = "driemaal dezelfde stelling (remise)"

    # ---------------------------------------------------------------- timer
    def _timer_mark_move(self):
        """Call after a move completes – marks the clock as started."""
        self._timer_started = True

    def _update_timer(self, dt):
        """Decrement active timers by dt (seconds). Called once per frame."""
        if self.game_over or not self._timer_started:
            return
        if self.timer_type == "clock":
            if self.board.current_turn == Color.WHITE:
                self.timer_white -= dt
            else:
                self.timer_black -= dt
            if self.timer_white <= 0:
                self.timer_white = 0
                self.game_over = True
                self.winner = "Zwart"
                self.win_reason = "tijd (wit)"
                self._play_game_over()
            elif self.timer_black <= 0:
                self.timer_black = 0
                self.game_over = True
                self.winner = "Wit"
                self.win_reason = "tijd (zwart)"
                self._play_game_over()
        elif self.timer_type == "capture":
            # Shared countdown: when it runs out, the player who captured the
            # most piece-value points wins.
            self.timer_total -= dt
            if self.timer_total <= 0:
                self.timer_total = 0
                self.game_over = True
                self._play_game_over()
                self._finish_capture_round()

    def _capture_points(self, color):
        """Total piece-value points this color has captured this round."""
        return sum(self._value(p.piece_type) for p in self.board.captured_pieces[color])

    def _finish_capture_round(self):
        """Decide the capture round by the most captured points."""
        pts_w = self._capture_points(Color.WHITE)
        pts_b = self._capture_points(Color.BLACK)
        if pts_w > pts_b:
            self.winner = "Wit"
            self.win_reason = f"{pts_w} punten ({pts_w} - {pts_b})"
        elif pts_b > pts_w:
            self.winner = "Zwart"
            self.win_reason = f"{pts_b} punten ({pts_w} - {pts_b})"
        else:
            self.winner = None
            self.win_reason = f"gelijke punten ({pts_w} - {pts_b})"

    @staticmethod
    def _format_time(seconds):
        seconds = max(0, int(seconds))
        m, s = divmod(seconds, 60)
        return f"{m}:{s:02d}"

    # ---------------------------------------------------------------- AI
    def _request_ai_move(self):
        self.ai_thinking = True
        self.ai_move = None
        self.ai_think_start = time.time()
        board = self.board.clone()
        t = threading.Thread(target=self._ai_worker, args=(board,), daemon=True)
        t.start()

    def _ai_thinking_time(self, num_moves):
        """Random human-like thinking duration (seconds) for the AI, longer
        when the position offers more options."""
        ranges = {
            "easy": (0.8, 2.0),
            "medium": (1.5, 4.0),
            "hard": (2.5, 6.0),
        }
        lo, hi = ranges.get(self.ai_difficulty, (1.5, 4.0))
        target = random.uniform(lo, hi)
        scale = 0.8 + min(0.8, num_moves * 0.02)
        return target * scale

    def _ai_worker(self, board):
        move = self.ai.choose_move(board)
        # Wait a human-like time before revealing the move. If the search
        # already took longer, apply the move immediately.
        num_moves = len(board.get_all_moves(board.current_turn))
        remaining = self._ai_thinking_time(num_moves) - (time.time() - self.ai_think_start)
        if remaining > 0:
            time.sleep(remaining)
        self.ai_move = move
        self.ai_thinking = False

    def _apply_ai_move_if_ready(self):
        if self.game_over:
            return
        if self.ai_move is not None and not self.ai_thinking:
            move = self.ai_move
            self.ai_move = None
            (fr, fc), (tr, tc) = move
            self._do_move(fr, fc, tr, tc)

    # ---------------------------------------------------------------- drawing
    def run(self):
        while True:
            dt = self.clock.tick(60) / 1000.0  # seconds since last frame

            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    return
                if self.state == "menu":
                    self._menu_event(event)
                elif self.state == "game":
                    self._game_event(event)
                elif self.state == "rules":
                    self._rules_event(event)
                elif self.state == "credits":
                    self._credits_event(event)
                elif self.state == "slots":
                    self._slot_event(event)

            if self.state == "menu":
                self._draw_menu()
            elif self.state == "game":
                self._update_timer(dt)
                self._apply_ai_move_if_ready()
                self._draw_game()
            elif self.state == "rules":
                self._draw_rules()
            elif self.state == "credits":
                self._draw_credits()
            elif self.state == "slots":
                if self._slot_return == "menu":
                    self._draw_menu()
                else:
                    self._draw_game()
                self._draw_slots_overlay()

            pygame.display.flip()

    def _draw_menu(self):
        self.screen.fill(DARK_GRAY)
        if self._menu_title_pos:
            text, cx, y = self._menu_title_pos
            t = self.font_large.render(text, True, WHITE)
            self.screen.blit(t, t.get_rect(center=(cx, y)))
        for text, x, y in self._menu_label_items:
            lab = self.font_medium.render(text, True, WHITE)
            self.screen.blit(lab, (x, y))
        for b in self.menu_buttons:
            b.draw(self.screen)
        if self._menu_notice:
            t = self.font_small.render(self._menu_notice, True, (200, 160, 80))
            self.screen.blit(t, t.get_rect(center=(self.screen_width // 2,
                                                   self.screen_height - 16)))

    def _draw_rules(self):
        self.screen.fill(DARK_GRAY)
        cx = self.screen_width // 2
        y = 35 if self.square_size <= 60 else 140

        title = self.font_large.render("Speluitleg", True, WHITE)
        self.screen.blit(title, title.get_rect(center=(cx, y)))
        y += 50

        rules = [
            "PylonChess: schaken als één of twee spelers.",
            "",
            "Doel: zet de tegenstander schaakmat.",
            "",
            "Zetregels per stuk:",
            "  Pion: vooruit, slaat schuin; Toren: horizontaal/verticaal",
            "  Paard: L-vorm (2+1); Loper: diagonaal",
            "  Koningin: toren + loper; Koning: 1 veld, elke richting",
            "",
            "Rokade: koning + toren onbewogen, pad vrij.",
            "En passant: vang een pion die net langsging.",
            "Promotie: kies dame, toren, loper of paard.",
            "",
            "Pat = remise, net als 50 zetten zonder slaan of",
            "pionzet, en driemaal dezelfde stelling.",
            "",
            "H: hint, S: opslaan, L: laden, P: PGN-bestand.",
            "M: geluid aan/uit.",
            "",
            "Timer in het menu:",
            "  Uit: gewoon schaken.",
            "  Schaakklok: elke speler eigen tijd; zonder tijd verlies je.",
            "  Slaan: gedeelde tijd, zoveel mogelijk vijandelijke stukken",
            "         slaan; na afloop wint de meeste punten (remise bij",
            "         gelijke punten).",
            "",
            "Punten: pion 1, paard 3, loper 3, toren 5, dame 9.",
            "",
            "Zetten terug: U of knop Terug, opnieuw: Y/Verder.",
        ]
        spacing = 17 if self.square_size <= 60 else 22
        for line in rules:
            t = self.font_small.render(line, True, WHITE)
            self.screen.blit(t, (cx - 260, y))
