    def _rules_event(self, event):
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_ESCAPE:
                self.state = "menu"
                self._build_menu()
                return
            if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE,
                             pygame.K_TAB, pygame.K_UP, pygame.K_DOWN,
                             pygame.K_LEFT, pygame.K_RIGHT):
                self.state = "menu"
                self._build_menu()
                return
        if hasattr(self, '_back_btn') and self._back_btn.handle_event(event):
            self.state = "menu"
            self._build_menu()

    def _draw_credits(self):
        self.screen.fill(DARK_GRAY)
        cx = self.screen_width // 2
        y = 90 if self.square_size <= 60 else 140

        title = self.font_large.render("Credits", True, WHITE)
        self.screen.blit(title, title.get_rect(center=(cx, y)))
        y += 60

        credits = [
            "PylonChess",
            "",
            "Gemaakt door:",
            "",
            "Michiel Fokker",
            "(opdrachtgever & tester)",
            "",
            "opencode / big-pickle",
            "(AI-assistent & programmeur)",
            "",
            "Gebouwd met Python + pygame-ce",
        ]
        cspacing = 26 if self.square_size <= 60 else 30
        for line in credits:
            t = self.font_medium.render(line, True, WHITE)
            self.screen.blit(t, t.get_rect(center=(cx, y)))
            y += cspacing

        y += 20
        back = Button((cx - 80, y, 160, 38), "Terug (Esc)", self.font_small)
        back.focused = True
        back.draw(self.screen)
        self._back_btn = back

    def _credits_event(self, event):
        if event.type == pygame.KEYDOWN:
            if event.key == pygame.K_ESCAPE:
                self.state = "menu"
                self._build_menu()
                return
            if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE,
                             pygame.K_TAB, pygame.K_UP, pygame.K_DOWN,
                             pygame.K_LEFT, pygame.K_RIGHT):
                self.state = "menu"
                self._build_menu()
                return
        if hasattr(self, '_back_btn') and self._back_btn.handle_event(event):
            self.state = "menu"
            self._build_menu()
            return

    def _draw_game(self):
        self.screen.fill(DARK_GRAY)
        self._draw_coord_border()
        ox, oy = self._board_origin()
        self._draw_captures()
        self._draw_board(ox, oy)
        self._draw_left_sidebar()
        self._draw_sidebar()
        self._draw_status(oy)
        if self._pending_promotion:
            self._draw_promotion_picker()

    # ---------------------------------------------------------------- coord border
    def _draw_coord_border(self):
        """Draw coordinate labels (a-h, 1-8) around the board."""
        cb = BOARD_COORD_BORDER
        ox, oy = self._board_origin()
        size = self.square_size

        # Background strip behind the left column and bottom row of labels
        left_rect = pygame.Rect(self.board_x - cb, oy, cb, self.board_px)
        pygame.draw.rect(self.screen, PANEL, left_rect)
        bot_rect = pygame.Rect(self.board_x, oy + self.board_px, self.board_px, cb)
        pygame.draw.rect(self.screen, PANEL, bot_rect)

        # Left border: rank numbers 1-8
        for screen_row in range(8):
            board_row = 7 - screen_row if self.flipped else screen_row
            rank = str(board_row + 1)
            t = self.font_small.render(rank, True, WHITE)
            tx = self.board_x - cb + cb // 2 - t.get_width() // 2
            ty = oy + screen_row * size + size // 2 - t.get_height() // 2
            self.screen.blit(t, (tx, ty))

        # Bottom border: file letters a-h
        for screen_col in range(8):
            board_col = 7 - screen_col if self.flipped else screen_col
            letter = chr(ord('a') + board_col)
            t = self.font_small.render(letter, True, WHITE)
            tx = self.board_x + screen_col * size + size // 2 - t.get_width() // 2
            ty = oy + self.board_px + cb // 2 - t.get_height() // 2
            self.screen.blit(t, (tx, ty))

    # ---------------------------------------------------------------- captures
    def _draw_captures(self):
        """Draw captured pieces. Top strip = opponent's lost pieces,
        bottom strip = human's lost pieces. When flipped, swap accordingly."""
        size = self.square_size
        icon_size = size * 0.5 if size > 60 else size * 0.3

        # Determine which captured lists go on top/bottom
        # Top strip = pieces taken by the player whose pieces are at the top
        # Bottom strip = pieces taken by the player whose pieces are at the bottom
        if self.mode == "ai":
            # AI mode: the computer's lost pieces go on top,
            # the human's lost pieces go on the bottom strip.
            human_side = Color.BLACK if self.ai_side == Color.WHITE else Color.WHITE
            top_lost = self.board.captured_pieces[self.ai_side]
            top_label = "GESLAGEN door " + ("Zwart" if human_side == Color.WHITE else "Wit") + ":"
            bot_lost = self.board.captured_pieces[human_side]
            bot_label = "GESLAGEN door " + ("Zwart" if self.ai_side == Color.WHITE else "Wit") + ":"
        elif self.flipped:
            # Black at top, White at bottom
            top_lost = self.board.captured_pieces[Color.BLACK]   # black pieces lost (top player)
            bot_lost = self.board.captured_pieces[Color.WHITE]   # white pieces lost (bottom player)
            top_label = "GESLAGEN door Zwart:"
            bot_label = "GESLAGEN door Wit:"
        else:
            # White at top (normal), Black at bottom
            top_lost = self.board.captured_pieces[Color.WHITE]   # white pieces lost (top player)
            bot_lost = self.board.captured_pieces[Color.BLACK]   # black pieces lost (bottom player)
            top_label = "GESLAGEN door Wit:"
            bot_label = "GESLAGEN door Zwart:"

        # Background panels (aligned with the board's left edge)
        cb = BOARD_COORD_BORDER
        bx = self.board_x
        top_rect = pygame.Rect(bx, 0, self.board_px, self.capture_strip)
        pygame.draw.rect(self.screen, PANEL, top_rect)
        pygame.draw.rect(self.screen, (70, 70, 70), top_rect, 1)
        bot_rect = pygame.Rect(bx, self.capture_strip + cb + self.board_px + cb,
                               self.board_px, self.capture_strip)
        pygame.draw.rect(self.screen, PANEL, bot_rect)
        pygame.draw.rect(self.screen, (70, 70, 70), bot_rect, 1)

        # Labels
        cb = BOARD_COORD_BORDER
        top_lbl = self.font_tiny.render(top_label, True, GRAY)
        self.screen.blit(top_lbl, (bx + 8, 6))
        bot_lbl = self.font_tiny.render(bot_label, True, GRAY)
        self.screen.blit(bot_lbl, (bx + 8, self.capture_strip + cb + self.board_px + cb + 6))

        self._draw_capture_row(top_lost, bx + 8, self.capture_strip // 2, icon_size)
        self._draw_capture_row(bot_lost, bx + 8, self.capture_strip + cb + self.board_px + cb +
                               self.capture_strip // 2, icon_size)

    def _draw_capture_row(self, pieces, x_start, cy, icon_size):
        if not pieces:
            return
        right_edge = self.board_x + self.board_px
        x = x_start + 110
        for p in sorted(pieces, key=lambda p: self._value(p.piece_type)):
            cx = x + icon_size / 2
            self._draw_piece_shape(p.piece_type, p.color, cx, cy, icon_size)
            x += icon_size + 6
            if x > right_edge - icon_size:
                break

    def _value(self, pt):
        return CAPTURE_POINTS.get(pt, 0)

    # ---------------------------------------------------------------- board
    def _draw_board(self, ox, oy):
        size = self.square_size
        for board_row in range(8):
            for board_col in range(8):
                sr, sc = self._board_to_screen(board_row, board_col)
                x = ox + sc * size
                y = oy + sr * size
                is_light = (board_row + board_col) % 2 == 0
                color = LIGHT_SQUARE if is_light else DARK_SQUARE
                pygame.draw.rect(self.screen, color, (x, y, size, size))

                # Selected piece: translucent green tint over the square
                if self.selected_piece and (board_row, board_col) == self.selected_piece:
                    self._blit_tint(x, y, size, size, HIGHLIGHT_COLOR, 150)
                elif self.last_move and (board_row, board_col) in [self.last_move[0], self.last_move[1]]:
                    self._blit_tint(x, y, size, size, LAST_MOVE_COLOR, 110)
                elif self.hint_move and (board_row, board_col) in [self.hint_move[0], self.hint_move[1]]:
                    self._blit_tint(x, y, size, size, HINT_COLOR, 100)
                elif (board_row, board_col) in self.valid_moves:
                    self._blit_tint(x, y, size, size, HIGHLIGHT_COLOR, 90)
                elif not self.game_over and self.board.is_in_check(self.board.current_turn):
                    piece = self.board.get_piece(board_row, board_col)
                    if piece and piece.piece_type == PieceType.KING and \
                       piece.color == self.board.current_turn:
                        self._blit_tint(x, y, size, size, CHECK_COLOR, 120)

                # move indicators
                if (board_row, board_col) in self.valid_moves:
                    px = x + size // 2
                    py = y + size // 2
                    dot = pygame.Surface((size, size), pygame.SRCALPHA)
                    if self.board.get_piece(board_row, board_col):
                        pygame.draw.circle(dot, (*HIGHLIGHT_COLOR, 160),
                                           (px - x, py - y), size // 2 - 6, 4)
                    else:
                        pygame.draw.circle(dot, (*HIGHLIGHT_COLOR, 150),
                                           (px - x, py - y), size // 7)
                    self.screen.blit(dot, (x, y))

                # piece
                piece = self.board.get_piece(board_row, board_col)
                if piece:
                    self._draw_piece_shape(piece.piece_type, piece.color,
                                           x + size // 2, y + size // 2 + 5, size * 0.55)

    def _blit_tint(self, x, y, w, h, rgb, alpha):
        """Blit a translucent color rectangle over an area of the board."""
        surf = pygame.Surface((w, h), pygame.SRCALPHA)
        surf.fill((*rgb, alpha))
        self.screen.blit(surf, (x, y))

    # ---------------------------------------------------------------- sidebar
    def _draw_left_sidebar(self):
        """Sidebar to the LEFT of the board: match info (move count & history)."""
        sx = 16
        y = self.capture_strip + 8

        # Title
        title = self.font_medium.render("PylonChess", True, WHITE)
        self.screen.blit(title, (sx, y))
        y += 30

        # Mode / opponent
        if self.mode == "ai":
            mode_txt = "Tegen computer"
            diff_txt = "Niveau: " + DIFFICULTY_LABELS[self.ai_difficulty]
            side_txt = "Jij speelt: " + ("Wit" if self.ai_side == Color.BLACK else "Zwart")
        else:
            mode_txt = "Twee spelers"
            diff_txt = ""
            side_txt = "Onderaan: " + ("Wit" if self.pvp_bottom == Color.WHITE else "Zwart")
        for line in (mode_txt, diff_txt, side_txt):
            if not line:
                continue
            t = self.font_small.render(line, True, GRAY)
            self.screen.blit(t, (sx, y))
            y += 20
        y += 8

        # Remaining time for the active timer types
        if self.timer_type == "clock":
            t = self.font_small.render(
                "Wit: " + self._format_time(self.timer_white or 0), True, GRAY)
            self.screen.blit(t, (sx, y))
            y += 17
            t = self.font_small.render(
                "Zwart: " + self._format_time(self.timer_black or 0), True, GRAY)
            self.screen.blit(t, (sx, y))
            y += 17
        elif self.timer_type == "capture":
            t = self.font_small.render(
                "Tijd: " + self._format_time(self.timer_total or 0), True, GRAY)
            self.screen.blit(t, (sx, y))
            y += 17
        y += 8

        # Move counter
        t = self.font_medium.render("Zetten: " + str(len(self.board.move_history)), True, WHITE)
        self.screen.blit(t, (sx, y))
        y += 28

        # Move history (algebraic notation when available)
        t = self.font_small.render("Zetgeschiedenis:", True, GRAY)
        self.screen.blit(t, (sx, y))
        y += 20
        pair = 1
        for i in range(0, len(self.board.move_history), 2):
            m1 = self.board.move_history[i]
            line = f"{pair}. {m1.get('san', self._move_str(m1))}"
            if i + 1 < len(self.board.move_history):
                m2 = self.board.move_history[i + 1]
                line += "  " + m2.get("san", self._move_str(m2))
            t = self.font_tiny.render(line, True, GRAY)
            self.screen.blit(t, (sx, y))
            y += 18
            pair += 1
            if y > self.screen_height - 60:
                break

    def _top_color(self):
        """Which color's pieces start at the top of the screen."""
        return Color.BLACK if self.flipped else Color.WHITE

    def _bottom_color(self):
        """Which color's pieces start at the bottom of the screen."""
        return Color.WHITE if self.flipped else Color.BLACK

    def _home_center_y(self, color):
        """Vertical center (screen y) of a player's starting rank on the board."""
        board_row = 0 if color == Color.WHITE else 7
        screen_row, _ = self._board_to_screen(board_row, 0)
        oy = self.capture_strip + BOARD_COORD_BORDER
        return oy + screen_row * self.square_size + self.square_size // 2

    def _draw_clock_panel(self, sx, w, cy, color, active, time_text, low_time, extra_text=None):
        """Draw one player's clock as a panel centered at cy. With extra_text
        a third line is added (used by the capture mode to show points)."""
        h = 66 if extra_text else 46
        rect = pygame.Rect(sx, cy - h // 2, w, h)
        pygame.draw.rect(self.screen, BUTTON_ACTIVE if active else PANEL, rect, border_radius=10)
        pygame.draw.rect(self.screen, WHITE if active else (70, 70, 70), rect, 2, border_radius=10)

        cx = sx + w // 2
        name = "Wit" if color == Color.WHITE else "Zwart"
        nm = self.font_small.render(name, True, WHITE)
        tm = self.font_medium.render(time_text, True, CHECK_COLOR if low_time else WHITE)
        if extra_text:
            em = self.font_small.render(extra_text, True, (140, 220, 140))
            self.screen.blit(nm, nm.get_rect(center=(cx, cy - 20)))
            self.screen.blit(tm, tm.get_rect(center=(cx, cy + 2)))
            self.screen.blit(em, em.get_rect(center=(cx, cy + 22)))
        else:
            self.screen.blit(nm, nm.get_rect(center=(cx, cy - 9)))
            self.screen.blit(tm, tm.get_rect(center=(cx, cy + 8)))

    def _draw_sidebar(self):
        """Sidebar to the RIGHT of the board: each player's clock next to the
        pieces at their starting rank, turn indicator centered in between."""
        sx = self.board_x + self.board_px + 16
        w = self.sidebar_width - 28
        cx = sx + w // 2

        top_color = self._top_color()
        bot_color = self._bottom_color()
        top_y = self._home_center_y(top_color)
        bot_y = self._home_center_y(bot_color)
        mid_y = (top_y + bot_y) // 2
        turn = self.board.current_turn

        # Clocks: only shown next to each player's starting rank when a time
        # option is selected in the main menu.
        if self.timer_type == "clock":
            for color, cy in ((top_color, top_y), (bot_color, bot_y)):
                secs = max(0, int((self.timer_white if color == Color.WHITE else self.timer_black) or 0))
                self._draw_clock_panel(sx, w, cy, color,
                                       active=(turn == color and not self.game_over),
                                       time_text=self._format_time(secs),
                                       low_time=secs <= 30)
        elif self.timer_type == "capture":
            secs = max(0, int(self.timer_total or 0))
            low_time = secs <= 30
            for color, cy in ((top_color, top_y), (bot_color, bot_y)):
                self._draw_clock_panel(
                    sx, w, cy, color,
                    active=(turn == color and not self.game_over),
                    time_text=self._format_time(secs),
                    low_time=low_time,
                    extra_text=f"Punten: {self._capture_points(color)}")

        # Turn indicator / result in the middle
        if self.game_over:
            # Winner (or "Remise") on top, the points below.
            top_text = (self.winner + " wint") if self.winner else "Remise"
            pw = self._capture_points(Color.WHITE)
            pb = self._capture_points(Color.BLACK)
            if pw + pb > 0 or self.timer_type == "capture":
                bot_text = f"Punten: {pw} - {pb}"
            else:
                bot_text = self.win_reason
            t = self.font_medium.render(top_text, True, BUTTON_ACTIVE)
            self.screen.blit(t, t.get_rect(center=(cx, mid_y - 10)))
            t = self.font_small.render(bot_text, True, GRAY)
            self.screen.blit(t, t.get_rect(center=(cx, mid_y + 14)))
        else:
            if self.mode == "ai" and turn == self.ai_side:
                turn_text = "Computer denkt..."
            else:
                who = "Wit" if turn == Color.WHITE else "Zwart"
                if self.mode == "ai" and turn == self.ai_side:
                    turn_text = who + " (computer)"
                else:
                    turn_text = who + " aan zet"
                if self.board.is_in_check(turn):
                    turn_text += "  - SCHAAK!"
            col = CHECK_COLOR if "SCHAAK" in turn_text else WHITE
            t = self.font_medium.render(turn_text, True, col)
            self.screen.blit(t, t.get_rect(center=(cx, mid_y)))

        # Undo / redo buttons; replaced by a prominent restart button when the
        # game is finished (these no longer make sense while the game is over).
        by = self.screen_height - 80
        if self.game_over:
            bw2 = (w - 8) // 2
            self.btn_undo = None
            self.btn_redo = None
            self.btn_hint = None
            self.btn_save = None
            self.btn_slots = None
            self.btn_restart = Button((sx, by, bw2, 32), "Opnieuw", self.font_tiny,
                                      BUTTON_ACTIVE, BUTTON_ACTIVE_HOVER)
            self.btn_settings = Button((sx + bw2 + 8, by, bw2, 32), "Instellingen",
                                       self.font_tiny, (100, 100, 100), (130, 130, 130))
            self.btn_restart.draw(self.screen)
            self.btn_settings.draw(self.screen)
        else:
            b3w = (w - 16) // 3
            self.btn_restart = None
            self.btn_settings = None
            self.btn_hint = Button((sx, by - 32, b3w, 28), "Hint (H)", self.font_tiny,
                                   (70, 90, 150), (100, 140, 210))
            self.btn_undo = Button((sx + b3w + 8, by - 32, b3w, 28), "Terug", self.font_tiny,
                                   (100, 100, 100), (130, 130, 130))
            self.btn_redo = Button((sx + 2 * (b3w + 8), by - 32, b3w, 28), "Verder", self.font_tiny,
                                   (100, 100, 100), (130, 130, 130))
            bw_s = (w - 8) // 2
            self.btn_save = Button((sx, by + 4, bw_s, 28), "Opslaan (S)", self.font_tiny,
                                   (60, 110, 60), (90, 150, 90))
            self.btn_slots = Button((sx + bw_s + 8, by + 4, bw_s, 28), "Slots (L)", self.font_tiny,
                                    (70, 90, 150), (100, 140, 210))
            self.btn_hint.draw(self.screen)
            self.btn_undo.draw(self.screen)
            self.btn_redo.draw(self.screen)
            self.btn_save.draw(self.screen)
            self.btn_slots.draw(self.screen)

        # Controls hint at bottom
        y = self.screen_height - 34
        t = self.font_tiny.render("U:terug  Y:verder  H:hint  R:nieuw", True, GRAY)
        self.screen.blit(t, (sx, y))
        t = self.font_tiny.render("S:opslaan  L:laden  P:PGN  M:geluid", True, GRAY)
        self.screen.blit(t, (sx, y + 14))

    def _move_str(self, mv):
        fr, to = mv['from'], mv['to']
        return f"{chr(97+fr[1])}{8-fr[0]}-{chr(97+to[1])}{8-to[0]}"

    # ---------------------------------------------------------------- status
    def _draw_status(self, oy):
        y = self.screen_height - 34
        col = GRAY
        if self._notice is not None and time.time() >= self._notice[1]:
            self._notice = None
        if self._pending_promotion:
            status = "Kies een promotiestuk (Esc = annuleren)"
            col = WHITE
        elif self._notice is not None:
            status = self._notice[0]
            col = (140, 220, 140)
        elif self.hint_thinking:
            status = "De hint wordt berekend..."
        elif self.selected_piece:
            status = "Kies een geldige zet (groene velden)"
        elif self.ai_thinking:
            status = "De computer is aan het nadenken..."
        elif self.game_over:
            status = "Spel afgelopen. Klik Opnieuw of druk R voor een nieuw spel."
        else:
            status = "Klik op een stuk om te selecteren"
        t = self.font_small.render(status, True, col)
        self.screen.blit(t, (self.board_x + 10, y))

    # ================================================================ pieces
    def _draw_piece_shape(self, ptype, color, cx, cy, size):
        """Draw a round/cartoonish chess piece using vector shapes.
        cx, cy = center, size = target height in px."""
        if color == Color.WHITE:
            fill = WHITE
            outline = (60, 60, 60)
            shade = (200, 200, 200)
        else:
            fill = (60, 60, 65)
            outline = (0, 0, 0)
            shade = (90, 90, 100)

        u = size / 5.8  # unit - piece height spans roughly 6 units

        if ptype == PieceType.PAWN:
            self._pawn(cx, cy, u, fill, outline, shade, color)
        elif ptype == PieceType.ROOK:
            self._rook(cx, cy, u, fill, outline, shade)
        elif ptype == PieceType.KNIGHT:
            self._knight(cx, cy, u, fill, outline, shade)
        elif ptype == PieceType.BISHOP:
            self._bishop(cx, cy, u, fill, outline, shade)
        elif ptype == PieceType.QUEEN:
            self._queen(cx, cy, u, fill, outline, shade)
        elif ptype == PieceType.KING:
            self._king(cx, cy, u, fill, outline, shade)

    def _base(self, cx, cy, u, fill, outline, w=5.0, top=0.6, bot=2.6):
        pygame.draw.polygon(self.screen, fill, [
            (cx - w * u, cy + top * u), (cx + w * u, cy + top * u),
            (cx + w * 0.9 * u, cy + bot * u), (cx - w * 0.9 * u, cy + bot * u)])
        pygame.draw.polygon(self.screen, outline, [
            (cx - w * u, cy + top * u), (cx + w * u, cy + top * u),
            (cx + w * 0.9 * u, cy + bot * u), (cx - w * 0.9 * u, cy + bot * u)], 2)

    def _body(self, cx, cy, u, fill, outline, shade, t, b, w):
        # rounded body via trapezoid
        pygame.draw.polygon(self.screen, fill, [
            (cx - w * u, cy + t * u), (cx + w * u, cy + t * u),
            (cx + w * 1.25 * u, cy + b * u), (cx - w * 1.25 * u, cy + b * u)])
        pygame.draw.polygon(self.screen, outline, [
            (cx - w * u, cy + t * u), (cx + w * u, cy + t * u),
            (cx + w * 1.25 * u, cy + b * u), (cx - w * 1.25 * u, cy + b * u)], 2)

    def _pawn(self, cx, cy, u, fill, outline, shade, color):
        # base
        self._base(cx, cy, u, fill, outline, w=2.6, top=1.2, bot=2.4)
        # body (skirt)
        self._body(cx, cy, u, fill, outline, shade, t=-0.4, b=1.3, w=1.7)
        # collar
        pygame.draw.polygon(self.screen, fill, [
            (cx - 1.7*u, cy - 0.9*u), (cx + 1.7*u, cy - 0.9*u),
            (cx + 1.3*u, cy - 0.3*u), (cx - 1.3*u, cy - 0.3*u)])
        pygame.draw.polygon(self.screen, outline, [
            (cx - 1.7*u, cy - 0.9*u), (cx + 1.7*u, cy - 0.9*u),
            (cx + 1.3*u, cy - 0.3*u), (cx - 1.3*u, cy - 0.3*u)], 2)
        # neck
        pygame.draw.polygon(self.screen, fill, [
            (cx - 0.9*u, cy - 0.3*u), (cx + 0.9*u, cy - 0.3*u),
            (cx + 0.75*u, cy - 1.6*u), (cx - 0.75*u, cy - 1.6*u)])
        pygame.draw.polygon(self.screen, outline, [
            (cx - 0.9*u, cy - 0.3*u), (cx + 0.9*u, cy - 0.3*u),
            (cx + 0.75*u, cy - 1.6*u), (cx - 0.75*u, cy - 1.6*u)], 2)
        # head
        pygame.draw.circle(self.screen, fill, (int(cx), int(cy - 2.4 * u)), int(1.3 * u))
        pygame.draw.circle(self.screen, outline, (int(cx), int(cy - 2.4 * u)), int(1.3 * u), 2)

    def _rook(self, cx, cy, u, fill, outline, shade):
        # base
        self._base(cx, cy, u, fill, outline, w=2.5, top=1.6, bot=2.7)
        # body
        self._body(cx, cy, u, fill, outline, shade, t=-0.2, b=1.7, w=1.6)
        # crown base
        pygame.draw.rect(self.screen, fill, (int(cx-1.6*u), int(cy-2.0*u), int(3.2*u), int(1.8*u)))
        pygame.draw.rect(self.screen, outline, (int(cx-1.6*u), int(cy-2.0*u), int(3.2*u), int(1.8*u)), 2)
        # crenellations
        for dx in [-1.3, -0.43, 0.43, 1.3]:
            pygame.draw.rect(self.screen, fill,
                             (int(cx+dx*u-0.43*u), int(cy-3.2*u), int(0.86*u), int(1.4*u)))
            pygame.draw.rect(self.screen, outline,
                             (int(cx+dx*u-0.43*u), int(cy-3.2*u), int(0.86*u), int(1.4*u)), 1)

    def _knight(self, cx, cy, u, fill, outline, shade):
        # base
        self._base(cx, cy, u, fill, outline, w=2.9, top=1.8, bot=2.6)
        # body
        self._body(cx, cy, u, fill, outline, shade, t=0.0, b=1.8, w=1.7)

        # head + neck silhouette (horse profile facing right)
        head = [
            # start at neck bottom-left
            (cx - 1.3*u, cy + 1.6*u),
            # left side of neck going up
            (cx - 1.1*u, cy - 0.5*u),
            # back of head / poll
            (cx - 0.6*u, cy - 2.8*u),
            # top of head / forehead
            (cx + 0.2*u, cy - 3.5*u),
            # ear tip
            (cx + 0.8*u, cy - 4.2*u),
            # behind ear
            (cx + 1.0*u, cy - 3.3*u),
            # forehead slope
            (cx + 1.4*u, cy - 2.8*u),
            # bridge of nose
            (cx + 2.2*u, cy - 2.0*u),
            # tip of muzzle
            (cx + 2.7*u, cy - 1.2*u),
            # chin
            (cx + 2.2*u, cy - 0.3*u),
            # jaw line
            (cx + 1.5*u, cy + 0.5*u),
            # throat
            (cx + 1.5*u, cy + 1.6*u),
        ]
        pygame.draw.polygon(self.screen, fill, head)
        pygame.draw.polygon(self.screen, outline, head, 2)

        # second ear (behind, just an outline triangle)
        pygame.draw.polygon(self.screen, outline, [
            (cx - 0.1*u, cy - 3.0*u), (cx - 0.5*u, cy - 4.0*u), (cx + 0.3*u, cy - 3.2*u)], 2)

        # eye
        pygame.draw.circle(self.screen, WHITE, (int(cx + 0.9*u), int(cy - 2.3*u)), int(0.32*u))
        pygame.draw.circle(self.screen, outline, (int(cx + 0.9*u), int(cy - 2.3*u)), int(0.32*u), 2)
        pygame.draw.circle(self.screen, outline, (int(cx + 0.95*u), int(cy - 2.35*u)), int(0.15*u))

        # nostril
        pygame.draw.circle(self.screen, outline, (int(cx + 2.3*u), int(cy - 1.3*u)), int(0.22*u), 2)

        # mouth line
        pygame.draw.line(self.screen, outline,
                         (int(cx + 2.0*u), int(cy - 0.7*u)), (int(cx + 2.6*u), int(cy - 1.1*u)), 2)

        # mane (3 pointed triangles along the back of the neck)
        for (mx, my, mh) in [(cx - 0.7*u, cy - 2.5*u, 1.0), (cx - 1.0*u, cy - 1.5*u, 0.8), (cx - 1.15*u, cy - 0.6*u, 0.6)]:
            pygame.draw.polygon(self.screen, outline, [
                (mx - 0.15*u, my), (mx - mh*0.5*u, my - mh*0.7*u), (mx + 0.15*u, my)], 2)

    def _bishop(self, cx, cy, u, fill, outline, shade):
        # base
        self._base(cx, cy, u, fill, outline, w=2.6, top=1.4, bot=2.5)
        # body
        self._body(cx, cy, u, fill, outline, shade, t=-0.3, b=1.5, w=1.6)
        # collar
        pygame.draw.polygon(self.screen, fill, [
            (cx - 1.9*u, cy - 0.9*u), (cx + 1.9*u, cy - 0.9*u),
            (cx + 1.4*u, cy - 0.3*u), (cx - 1.4*u, cy - 0.3*u)])
        pygame.draw.polygon(self.screen, outline, [
            (cx - 1.9*u, cy - 0.9*u), (cx + 1.9*u, cy - 0.9*u),
            (cx + 1.4*u, cy - 0.3*u), (cx - 1.4*u, cy - 0.3*u)], 2)
        # head with mitre slash
        pygame.draw.circle(self.screen, fill, (int(cx), int(cy - 1.9*u)), int(1.3*u))
        pygame.draw.circle(self.screen, outline, (int(cx), int(cy - 1.9*u)), int(1.3*u), 2)
        pygame.draw.line(self.screen, outline, (int(cx-1.0*u), int(cy-2.0*u)),
                         (int(cx+1.0*u), int(cy-1.7*u)), 2)
        # mitre point
        pygame.draw.polygon(self.screen, fill, [
            (cx, cy - 3.9*u), (cx - 1.1*u, cy - 2.9*u), (cx + 1.1*u, cy - 2.9*u)])
        pygame.draw.polygon(self.screen, outline, [
            (cx, cy - 3.9*u), (cx - 1.1*u, cy - 2.9*u), (cx + 1.1*u, cy - 2.9*u)], 2)
        # top ball
        pygame.draw.circle(self.screen, fill, (int(cx), int(cy - 4.1*u)), int(0.55*u))
        pygame.draw.circle(self.screen, outline, (int(cx), int(cy - 4.1*u)), int(0.55*u), 1)

    def _queen(self, cx, cy, u, fill, outline, shade):
        # base
        self._base(cx, cy, u, fill, outline, w=3.0, top=1.7, bot=2.8)
        # body
        self._body(cx, cy, u, fill, outline, shade, t=-0.2, b=1.8, w=1.9)
        # crown
        pts = [
            (cx - 2.2*u, cy - 1.2*u), (cx - 2.0*u, cy - 3.4*u),
            (cx - 1.2*u, cy - 2.9*u), (cx, cy - 4.3*u),
            (cx + 1.2*u, cy - 2.9*u), (cx + 2.0*u, cy - 3.4*u),
            (cx + 2.2*u, cy - 1.2*u),
        ]
        pygame.draw.polygon(self.screen, fill, pts)
        pygame.draw.polygon(self.screen, outline, pts, 2)
        # band
        pygame.draw.rect(self.screen, fill, (int(cx-2.2*u), int(cy-1.2*u), int(4.4*u), int(0.8*u)))
        pygame.draw.rect(self.screen, outline, (int(cx-2.2*u), int(cy-1.2*u), int(4.4*u), int(0.8*u)), 1)
        # gems
        for dx in [-1.2, 0, 1.2]:
            pygame.draw.circle(self.screen, outline, (int(cx+dx*u), int(cy-1.0*u)), int(0.35*u), 1)

    def _king(self, cx, cy, u, fill, outline, shade):
        # base
        self._base(cx, cy, u, fill, outline, w=2.7, top=1.5, bot=2.6)
        # body
        self._body(cx, cy, u, fill, outline, shade, t=-0.2, b=1.6, w=1.7)
        # band / collar
        pygame.draw.polygon(self.screen, fill, [
            (cx - 1.9*u, cy - 0.8*u), (cx + 1.9*u, cy - 0.8*u),
            (cx + 2.1*u, cy - 0.2*u), (cx - 2.1*u, cy - 0.2*u)])
        pygame.draw.polygon(self.screen, outline, [
            (cx - 1.9*u, cy - 0.8*u), (cx + 1.9*u, cy - 0.8*u),
            (cx + 2.1*u, cy - 0.2*u), (cx - 2.1*u, cy - 0.2*u)], 2)
        # head
        pygame.draw.circle(self.screen, fill, (int(cx), int(cy - 2.5*u)), int(1.8*u))
        pygame.draw.circle(self.screen, outline, (int(cx), int(cy - 2.5*u)), int(1.8*u), 2)
        # cross
        pygame.draw.rect(self.screen, fill, (int(cx-0.38*u), int(cy-5.3*u), int(0.76*u), int(2.8*u)))
        pygame.draw.rect(self.screen, outline, (int(cx-0.38*u), int(cy-5.3*u), int(0.76*u), int(2.8*u)), 1)
        pygame.draw.rect(self.screen, fill, (int(cx-1.6*u), int(cy-4.6*u), int(3.2*u), int(0.76*u)))
        pygame.draw.rect(self.screen, outline, (int(cx-1.6*u), int(cy-4.6*u), int(3.2*u), int(0.76*u)), 1)
